programs.sol:
"""Approximate sparse responses at code-literal and delimiter boundaries.

The rules recognize numeric suffixes, named arguments, callbacks, comments,
and a few declaration forms. Most tokens get zero. A short text tail supplies
local syntax; every document starts fresh. Constants are calibrated on training
examples, not token IDs. Lexical and longer-context variations are omitted.
"""
import re

READS = ()


def predict(s, previous, text):
    word = s.strip()
    # A number completed by a type marker, unit, or hexadecimal prefix.
    if text and text[-1] in '0123456789':
        number = re.search(
            r'(?<![\w.])(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)$', text)
        delimited = bool(number and text[:number.start()].rstrip().endswith(
            ('(', '=', ',', '*', '/', '+', '-', '{')))
        if delimited:
            if s == 'l':
                return -1.4
            if s in ('L', 'UL', 'ULL', 'LL'):
                return -6.8
            if s in ('f', 'F', 'D', 'd'):
                return (-3.9 if '.' in number[0]
                        else -0.5)
            units = {
                's': -0.6,
                'ms': -0.5,
                'ns': 0.0,
                'u': -0.5,
                'H': -1.9,
                'T': -1.3,
            }
            if s in units:
                return units[s]
        if number and number[0] == '0':
            if re.fullmatch(r'x[0-9a-fA-F]*', s):
                boundary = bool(re.search(r'[(,{]\s*0$', text))
                if s == 'x':
                    return -3.0 if boundary else -0.6
                return -1.1 if boundary else -0.1
            if s == '.' and re.search(r'[,{}]0$', text):
                return -0.6
    # Annotation fields and named arguments, as opposed to plain assignment.
    binding = re.fullmatch(r'=(?:[A-Za-z_]+|[\[\{"\']|\["|\[\')?', word)
    if binding and re.search(r'[A-Za-z_][\w.]*$', text):
        if re.search(r'(?:@[\w.]+|#?\[\w+)\([^)]*$', text):
            return (-5.3 if s.startswith(' ')
                    else -1.2)
        name = re.search(r'[(,]\s*([A-Za-z_]\w*)$', text)
        paren = text.rfind('(') > text.rfind(')')
        comma = bool(re.search(r',\s*[\w.]+$', text))
        if name and (paren or comma):
            if s.startswith(' '):
                return (-1.8 if len(name[1]) >= 3
                        else -0.4)
            return -0.5
    if word == '=>':
        return -1.3 if text.endswith(('"', "'")) else -0.2
    # Delimiters carried by a newline token affect the next indentation.
    if s and not s.strip(' ') and re.search(r'[,[(]\r?\n$', previous):
        if len(s) <= 2:
            return -0.8
        return (-0.4 if len(s) == 3
                else -0.2)
    if re.fullmatch(r'\},(?:\{|\s*)', word):
        return (-0.9 if '\t' in previous
                else -0.3)
    # Introduce another expression or a comment in comma-separated code.
    if previous.rstrip().endswith(','):
        callbacks = {
            'function': -1.8,
            'func': -1.7,
            'array': -0.5,
            'new': -0.8,
            'async': -1.2,
        }
        operators = {
            '-': -0.5,
            '&': -0.5,
            '@': -1.5,
            '//': -1.6,
            '#': -1.1,
            '...': -0.4,
            'sizeof': -2.4,
            'NULL': -1.0,
        }
        if word in callbacks:
            return callbacks[word]
        if word in operators:
            return operators[word]
        if word == 'line' and '"' in previous:
            return 1.0
    if word in ('#', '//', '...') and previous.isspace():
        if re.search(r',\s*$', text):
            return -2.8
    if word == 'new' and previous == '::':
        return -0.6
    if word in ('function', 'func', 'lambda') and (
            previous.strip() in ('return', '=') or previous.endswith('(')):
        return -0.6
    if word == ',@':
        return -0.9
    if word == '+' and '\n' in s:
        return -0.3
    if word == '+' and previous.endswith('\n') and ',' in previous:
        return -1.5
    # Type/schema syntax and declaration idioms.
    if word == '.class' and re.search(r'(?<![\w])[A-Z][A-Za-z_0-9]*$', text):
        return -3.4
    if word.upper() in ('CONSTRAINT', 'FOREIGN'):
        if word.isupper() or re.search(r'\n\s*$', text):
            return -1.9
    if previous == 'CONST' and s == 'RAINT':
        return -4.3
    if previous.strip() == 'using' and word in ('System', 'namespace'):
        return 1.5
    if previous.strip() == 'if' and word == 'let':
        return 1.6
    if previous.rstrip().endswith('(') and word in ('var', 'let'):
        return 1.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, text)
    return (doc, s, (text + s)[-192:]), float(value)

programs.haiku:
"""Layer 1 MLP down-projection, component 2944.

The component is quiet almost everywhere, with sharp negative dips at a few
kinds of token, nearly all in code argument lists, initialisers and literal data:

* `=` naming a field or argument inside an annotation, e.g. `@Column(name = "uuid")`:
  the strongest dip (about -6).
* `=` inside a call's parentheses: about -0.6, or about -1 once that call has a
  comma (a later named argument, e.g. `f(a, b, key = 1)`); `=` after a comma inside
  braces or brackets: about -0.3.
* A Java/C long suffix on a number, `0L`, `849L`: about -3 anywhere.
* A float or NMR suffix on a number inside a call: `1.5f` about -2.5, `1H` about -1.8.
* The `x` of a hex literal after `0` (`0x00`) inside brackets: about -2.
* The Java class literal `.class`: about -3.5.

Everything else is predicted as 0. The program tracks the open brackets of the
current document, so it knows whether a `=` sits inside an annotation or a list.
"""

import re

READS = ()

ANNOTATION_HEAD = re.compile(r"@[\w.]+\s*$")  # text before an "(" that opens an annotation
PLAIN_NUMBER = re.compile(r"^\d+(\.\d+)?$")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "stack": [], "text": "", "prev": ""}
    stack, prev = carry["stack"], carry["prev"]
    inner = stack[-1] if stack else None  # [kind, commas]: "@" annotation, "(", "[", "{"
    after_number = bool(PLAIN_NUMBER.match(prev))

    value = 0.0
    if tok.strip() == "=":
        if inner and inner[0] == "@":
            value = -6.0
        elif inner and inner[0] == "(":
            value = -1.0 if inner[1] > 0 else -0.6
        elif inner and inner[1] > 0:
            value = -0.3
    elif tok in ("L", "l") and after_number:
        value = -3.0
    elif tok in ("f", "F") and after_number and inner:
        value = -2.5 if inner[0] == "(" else -0.7
    elif tok == "H" and after_number and inner and inner[0] in "([":
        value = -1.8
    elif tok == "x" and prev == "0" and inner:
        value = -2.0
    elif tok == ".class":
        value = -3.5

    # update the bracket stack with this token's characters
    for ch in tok:
        if ch in "([{":
            kind = ch
            if ch == "(" and ANNOTATION_HEAD.search(carry["text"]):
                kind = "@"
            stack.append([kind, 0])
        elif ch in ")]}":
            if stack:
                stack.pop()
        elif ch == "," and stack:
            stack[-1][1] += 1
    carry["text"] = (carry["text"] + tok)[-80:]
    carry["prev"] = tok
    return carry, float(value)

programs.sol:
"""Approximate several early text-format and word-fragment responses.

The largest pulse marks `line` after a Python traceback's quoted filename.
Smaller rules recognize Arabic-script initial prefixes, split Greek function
words, Scandinavian reflexive possessives, Turkish mü, and dot filler.
These are surface-pattern approximations, not a complete language parser.
"""
import regex as re

READS = ()


def word_tail(text, script):
    match = re.search(r'\p{Script=' + script + r'}+$', text)
    return match[0] if match else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    context = previous[-120:]
    value = -0.0015

    if token == ' line':
        if re.search(r'\.py\w*[\"\']\s*,\s*$', context):
            value = -24.6
        elif re.search(r'<[^<>]+>[\"\']\s*,\s*$', context):
            value = -10.5
        elif re.search(r'[\"\']\s*,\s*$', context):
            value = -2.5
        elif re.search(r'\.py\s*$', context):
            value = -5.5

    if len(text) > 1 and set(text) == {'·'} and context.endswith('·'):
        value -= 0.96

    if re.fullmatch(r'\p{Script=Arabic}+', text):
        old = '' if token[0].isspace() else word_tail(context, 'Arabic')
        # Do not treat the weak letters alif/waw/ya as root consonants.
        short_consonants = len(text) <= 2 and text[0] not in 'اويى'
        # Arabic m-, t-, and y- word-initial prefixes.
        for letter, after, initial in (
            ('م', 2.1, 0.8),
            ('ت', 1.1, 1.0),
            ('ي', 1.8, 0.0),
        ):
            is_prefix = old in {letter, 'ال'+letter, 'لل'+letter,
                                'و'+letter, 'ب'+letter, 'ل'+letter}
            is_prefix |= bool(re.fullmatch('[وبفل]?ل?ال?'+letter, old))
            if is_prefix and short_consonants:
                value += after
            function_word = token.startswith(' ') and text in {
                'من', 'مع', 'ما', 'منذ', 'متى', 'تلك'
            }
            if not function_word and re.fullmatch(
                '[وبفل]?(?:ال)?'+letter+r'\p{Script=Arabic}{1,2}', text
            ):
                value += initial

    # Greek genitive endings and short pronoun/article fragments.
    old = '' if token[:1].isspace() else word_tail(context, 'Greek')
    if text == 'ου' and old in {'τ', 'μ', 'σ'}:
        value -= 3.2
    if text in {'α', 'ς'} and old in {'σ', 'σα', 'μ', 'μα'}:
        value -= 3.2
    if old and old+text in {'την', 'τον', 'στην', 'στον', 'της', 'τις', 'δεν'}:
        value -= 2.4

    # Scandinavian reflexive possessives, gated by nearby language cues.
    if text in {'sin', 'sine', 'si', 'sitt', 'sina'} and re.search(
        r'[åæøäö]|\b(?:och|att|og|jeg|som|det)\b', context, re.I
    ):
        value -= 2.5
    if text.casefold() == 'mü':
        value += 2.2

    return (doc, (previous + token)[-160:]), value

"""A syntax-sensitive signal for separators between mapping keys and values.

Closing-quote colons and colons after object-field names are positive;
ordinary prose, block headers, and type declarations are mostly quiet.
The first field of a JSON object on a new line is especially strong.
Underscore-separated names are weaker. Mapping arrows are also positive,
especially after quoted keys or a wildcard.
Negative cases include indentation following a file-listing header, an
initial Title: header, and paired middle-dot leaders. Only a bounded text
suffix is kept, and documents reset it.
"""
import re

READS = ()


def predict(token, before):
    if len(token) >= 2 and not token.strip('·'):
        return -2.88
    if token == ':' and before == 'Title':
        return -3.77
    if token and not token.strip(' '):
        if re.search(r'/[^\n ]+\.[A-Za-z0-9]+:\n$', before):
            return -0.10 * min(5, len(token))
    if ':' not in token and token != ' =>':
        return 0.0

    # Escaped code and line-numbered source listings use the same syntax.
    text = re.sub(r'\\+[nt]', '\n', before)
    text = re.sub(r'\\+(?=[\'\"])', '', text)
    text = re.sub(r'\n[ +-]*\d+\t[ \t]*', '\n', text)
    text = re.sub(r'\n[+-]', '\n', text)
    form = token.lstrip('\\')

    # A closing quote and colon complete a quoted field name.
    if form in ('":', "':"):
        quote = form[0]
        match = re.search(re.escape(quote) + r'([^\n' + quote + r']*)$', text)
        if match:
            key = match.group(1)
            boundary = text[:match.start()].rstrip()
            if boundary.endswith(('{', ',')):
                first = bool(re.search(r'(?:^|\n)\{\s*$', boundary))
                opened = boundary.endswith('{')
                if token.startswith('\\'):
                    return 2.65 if opened else 2.2
                if quote == "'":
                    return (2.3 if opened else 1.65) - 0.25 * ('_' in key)
                value = 2.85 if first else 2.2 if opened else 1.95
                return value - 0.4 * min(2, key.count('_'))
        return 0.03

    match = re.search(r'([\'\"][^\n\'\"]*[\'\"]|[\w$]+)\s*$', text)
    if token == ' =>':
        if text.rstrip().endswith('_'):
            return 0.7
        if match and match.group(1)[0] in '\'\"':
            return 1.85
        return 0.10

    # Bare fields: reject function parameters, declarations and TeX braces.
    if token == ':' and match:
        key = match.group(1)
        boundary = text[:match.start()].rstrip()
        brace = text.rfind('{')
        in_arguments = text.rfind('(') > max(brace, text.rfind(')'))
        listing = bool(re.search(r'\d+\t\s*[\w$]+$', before))
        in_record = (brace >= 0 or listing) and not in_arguments
        declaration = re.search(
            r'\b(?:class|interface|struct|enum)\b[^{}]*\{[^{}]*$', text
        )
        latex = re.search(r'\\[A-Za-z]+\{[^{}]*$', before)
        if (boundary.endswith(('{', ',')) and in_record
                and not declaration and not latex):
            if not key.isdigit() or (boundary.endswith('{')
                    and '\n' not in text[brace:]) or re.search(
                    r'\d+\s*:\s*[^,\n]+,\s*\d+$', text):
                return 2.15 - 0.25 * min(2, key.count('_'))
        return 0.02
    if form in ('":"', ':"', ":'"):
        return 0.70
    return -0.03


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-500:]), float(value)

programs.haiku:
"""Object-literal key colons: the colon right after a key inside a {...} object,
JSON, or dict literal (strongest after a quoted key such as "name":)."""
READS = ()

QUOTED_KEY_ENDS = ('":', "':", '\\":')   # a quoted key closed right before its colon
OBJECT_OPENERS = "(=,[:{"               # a '{' after one of these opens an object literal

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if prefix.position == 0 or carry is None:
        carry = ("", "", None)
    stack, last, doc = carry            # stack: open brackets, '{' as 'o' (object) or 'b' (block)
    if prefix.document_ids[-1] != doc:
        stack, last, doc = "", "", prefix.document_ids[-1]
    top = stack[-1] if stack else ""
    value = 0.0
    if cur.endswith(QUOTED_KEY_ENDS):
        value = 2.2 if stack else 1.1
    elif cur.endswith((':"', '":"')) and stack:
        value = 0.7
    elif cur == ":" and top == "o":
        value = 2.0
    elif cur == ":" and top == "b":
        value = 1.2
    elif cur == " =>":
        value = 0.5
    for ch in cur:
        if ch in "{[(":
            kind = ch
            if ch == "{":
                kind = "o" if (last == "" or last in OBJECT_OPENERS) else "b"
            stack += kind
        elif ch in "}])" and stack:
            stack = stack[:-1]
        if not ch.isspace():
            last = ch
    return (stack, last, doc), value

programs.sol:
"""Document-opening transients and a few decorative punctuation markers.

Initial word shape gives a coarse baseline. Bash shebangs, YAML titles,
Java's opening 'public', JavaScript wrappers and opening '12' have stronger
responses. Caret underlines retain their opening response while repeated.
Away from the opening, paired middle dots and completed flower punctuation
are positive; other weak, token-specific activity is left unexplained.
"""
READS = ()
FLOWER = '⁕'.encode('utf-8')


def initial_value(token):
    word = token.strip()
    if not word:
        return 0.28
    if word.isascii() and word.isdecimal():
        return 0.40 if int(word) <= 1 else -0.04
    if word.isalpha():
        if token.startswith(' '):
            return -0.17 if not word.islower() else -0.085
        if word.isascii():
            return -0.32 if not word.islower() else -0.27
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, opening, tail, caret_run = 0, '', b'', True
    else:
        _, position, opening, tail, caret_run = carry
    token = prefix.token_strings[-1]
    joined = tail + prefix.token_bytes[-1]
    value = 0.0
    if FLOWER in joined:
        value = 0.40
    elif token.strip() == '··':
        value = 0.516
    if position == 0:
        value = initial_value(token)

    if position < 3:
        opening += token
        if position == 0:
            if token == '<|endoftext|>':
                value = -2.17
            elif token == '#!/':
                value = -0.678
            elif token == '---\n':
                value = -0.325
            elif token == 'public':
                value = 1.904
            elif token == '(function':
                value = 0.439
        elif opening == '#!/bin':
            value = 0.163
        elif opening == '#!/bin/bash':
            value = 0.794
        elif opening == '#!/bin/sh':
            value = 0.621
        elif opening == '---\ntitle:':
            value = 0.854
        elif opening == '(function ()':
            value = 2.576
        elif position == 1 and opening == '12':
            value = 2.816

    caret_run = caret_run and bool(token) and not token.strip('^')
    if caret_run:
        value = 2.11 if len(token) >= 4 else 0.74
    return (doc, position + 1, opening, joined[-2:], caret_run), value

programs.haiku:
"""layers.1.mlp.down_proj:2948: a document-start component.

Inside a document this component is almost silent. Its one readable behaviour is
at the first token of a document (the token after <|endoftext|>, or the first
token of a packed row), where its value depends on what that token looks like:

  - a bare word starting with a letter and no leading space: negative, more so
    for longer words (about -0.1 for one letter, -0.2 for two, -0.4 for three or
    more), e.g. "The", "import", "package";
  - a word with a leading space (" the", " and"): about -0.1;
  - a lone space or other whitespace token: positive, about +0.37;
  - a digit: about +0.15; punctuation or symbols with a leading space: about +0.05;
  - anything else at the document start, and every later position: 0.

Predicted values are the means measured on training rows (rounded).
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()


def first_token_value(s: str) -> float:
    core = s.strip()
    if core == "":
        return 0.37
    if core[0].isalpha():
        if s.startswith(" "):
            return -0.1
        n = len(core)
        return -0.1 if n == 1 else (-0.2 if n == 2 else -0.4)
    if core[0].isdigit():
        return 0.15
    if s.startswith(" "):
        return 0.05
    return 0.0


def step(carry, prefix, upstream: Mapping):
    ids = prefix.document_ids
    is_first = len(ids) == 1 or ids[-1] != ids[-2]
    if not is_first:
        return carry, 0.0
    return carry, first_token_value(prefix.token_strings[-1])

programs.sol:
"""An initial-token signal, scaled by the token's written form.

It is strongest on words, intermediate on whitespace and punctuation,
and weak on digits (especially zero). The signal persists through exact
repetitions of the first token, then drops to a small background level.
Later chat role names get small positive values. Other later tokens are
near zero: this deliberately omits their weaker, context-specific responses.
The initial magnitude is a character-form approximation, not a token table.
"""
import math
import regex

READS = ()


def initial_value(text):
    word = text.strip()
    length = math.log2(max(1, len(word)))
    spaced = text.startswith(' ')
    if text == '<|im_start|>':
        return 11.86
    if text.startswith('<|') and text.endswith('|>'):
        return 6.7
    if not word:
        if '\n' in text or '\r' in text:
            return 4.8
        return 4.4 + 0.62 * math.log2(max(1, len(text)))
    if word.isascii():
        if word.isdigit():
            return -0.88 if int(word) == 0 else 2.14
        if word.isalpha():
            return ((8.95 if spaced else 6.85) + 0.45 * length
                    + 0.2 * word.istitle())
        if any(c.isalnum() for c in word):
            return 8.4 + 0.23 * length
        return (5.6 if spaced else 3.86) + 1.43 * length
    if '\ufffd' in word:
        return 6.85 + 2.4 * length
    if regex.search(r'\p{Script=Han}', word):
        return 5.6 + 0.26 * length
    if any(c.isalpha() for c in word):
        return 7.95
    return 4.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        initial_id, still_initial = token_id, True
    else:
        initial_id = carry[1]
        still_initial = carry[2] and token_id == initial_id
    value = -0.008
    if still_initial:
        value = initial_value(text)
    elif text == 'assistant':
        value = 0.55
    elif text == 'user':
        value = 0.29
    return (doc, initial_id, still_initial), value

"""Recognize fragments of written character encodings and escaped notation.

The strongest responses are inside hexadecimal byte escapes and numeric HTML
references. Byte-escape scores distinguish two/three-byte UTF-8 lead, middle, and final bytes.
Smaller responses mark printf conversions, TeX/markup fragments, and C1 controls.
Scores are approximate training means; ordinary contextual variation is omitted.
Only a short byte suffix is carried, resetting at document boundaries.
"""
import re

READS = ()

TEX_SPACING = {
    'hspace', 'vspace', 'hfill', 'vfill', 'phantom',
    'hphantom', 'vphantom', 'kern', 'mkern',
}
TEX_MATH_STRUCTURE = {
    'mathrel', 'mathop', 'stackrel', 'ensuremath',
}


def byte_escape(text, token):
    """Score an escape only when the newest token overlaps its two hex digits."""
    i = text.rfind('\\x')
    if i < 0:
        return None
    digits = re.match(r'[0-9a-fA-F]{0,2}', text[i + 2:])[0]
    if i + 2 + len(digits) <= len(text) - len(token):
        return None
    if len(digits) < 2:
        if not digits:
            return 0.49
        if '\\' in token:
            return 1.82 if digits.lower() in 'ab' else 0.45
        return 3.18

    byte = int(digits, 16)
    if 0xC0 <= byte < 0xE0:
        return 4.67  # UTF-8 lead for a two-byte character
    if 0xE0 <= byte < 0xF0:
        return 2.36  # UTF-8 lead for a three-byte character
    if 0x80 <= byte < 0xC0:
        before = text[:i].rstrip('\\')
        match = re.search(r'(?:\\+x[0-9a-fA-F]{2})+$', before)
        prior = []
        if match:
            prior = [int(h, 16) for h in
                     re.findall(r'\\x([0-9a-fA-F]{2})', match[0])]
        if prior and 0xE0 <= prior[-1] < 0xF0:
            return 5.05  # middle of a three-byte character
        if len(prior) > 1 and 0xE0 <= prior[-2] < 0xF0:
            return 5.80  # its final byte
        if prior and 0xC0 <= prior[-1] < 0xE0:
