import re

COMPLETED = re.compile(r"\\x([0-9a-fA-F])([0-9a-fA-F])$")  # \xHH just completed
PARTIAL = re.compile(r"\\x([0-9a-fA-F])$")                 # \xH, one digit so far
ESCAPE_START = re.compile(r"\\x$")                         # bare \x
ENTITY = re.compile(r"&#([0-9]+)$")                        # &#NN, digits so far

READS = ()


def byte_value(byte):
    """Activation for a completed \\xHH escape, by the byte's UTF-8 role."""
    if byte >= 0xF0:
        return 2.0  # 4-byte lead
    if byte >= 0xE0:
        return 2.5  # 3-byte lead
    if byte >= 0xC0:
        return 4.5  # 2-byte lead
    if byte >= 0x80:
        return 6.0  # continuation byte
    return 3.5  # ASCII control escape such as \x0c


def activation(text):
    m = COMPLETED.search(text)
    if m:
        return byte_value(int(m.group(1) + m.group(2), 16))
    m = PARTIAL.search(text)
    if m:
        return 3.2 if m.group(1) in "89" else 2.0 if m.group(1) in "ab" else 1.2
    if ESCAPE_START.search(text):
        return 0.5
    m = ENTITY.search(text)
    if m:
        return 5.5 if len(m.group(1)) >= 2 else 1.1
    return 0.0


