    # The carry is the recent text of this document; it resets at each new document.
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    text = "" if new_doc else carry
    text = (text + prefix.token_strings[-1])[-12:]
    return text, activation(text)

