        return state, -0.13 if before.rstrip().endswith((',', '.', ';', ':')) else v
    if s.strip().lower() == 'true':
        return state, 0.15
    v = chinese(s, before, split) if regex.search(r'\p{Script=Han}', s) else 0.0
    return state, float(v)

programs.haiku:
"""Layer-1 MLP component 2958 (down_proj): a reason-and-reaction word detector, plus
document openers.

It reads only the newest token and whether it starts a new document.
- Chinese words that introduce a cause (原因 "reason", 是因为 "is because", 正是/正因为/正如
  "precisely / just as") give a clear positive value.
- Words of praise, blame, gratitude or regret (感谢 thank, 感叹/惊叹 marvel, 怪 blame,
  怨 resent, 遗憾 regret, 赞 praise) give a smaller one.
- English "because" right after "just" or "simply" gives a positive one.
- The first token of a document has a fixed value by kind: code and markup openers
  positive, sentence-initial "The"/"A" mildly positive, and a leading package/digit negative.
Everywhere else it predicts 0.
"""

READS: tuple[str, ...] = ()

CAUSE = {"原因", "的原因", "主要原因", "是因为", "这是因为", "就是因为", "正是因为", "正因为",
         "之所以", "得益于", "源于"}
PRECISELY = {"正是", "正如", "就像", "诸如"}
REACTION = {"叹", "惊叹", "感叹", "感谢", "感激", "谢谢你", "愧", "可惜", "遗憾", "怨", "怪",
            "抱怨", "恨", "赞", "赞同", "赞扬", "点赞", "讚", "批评", "讽", "呼吁", "号召",
            "庆祝", "真是", "幸好"}
BECAUSE_AFTER = {" just", "Just", " simply"}
CODE_OPENERS = {"import", "#include", "#!/", "def", "//\n", "<!", "#", "\t", "<|endoftext|>"}
SENTENCE_OPENERS = {"The", "A", "In", "This"}
DOC_NEGATIVE = {"package", "1", "<|im_start|>", ","}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    value = 0.0
    if new_doc:
        if token in CODE_OPENERS:
            value = 1.0
        elif token in SENTENCE_OPENERS:
            value = 0.5
        elif token in DOC_NEGATIVE:
            value = -0.4
    elif token in CAUSE:
        value = 1.5
    elif token in PRECISELY:
        value = 2.0
    elif token in REACTION:
        value = 1.0
    elif token == "正式":
        value = 1.4
    elif token == " because" and prev in BECAUSE_AFTER:
        value = 2.0
    return carry, float(value)

programs.sol:
"""An initial-context signal, also retained for identical initial repeats.

Initial words are strongest when not preceded by a space. Indentation and
source-code declarations are especially strong; sentence punctuation,
newlines and East Asian text are weaker. These are coarse form classes,
not a vocabulary lookup. Away from the beginning, a local backslash rule
uses nearby TeX commands, ampersands and escaped quotes to choose a sign.
"""
import math
import regex
READS = ()

DECLARATIONS = {
    'package', 'namespace', 'class', 'struct', 'interface', 'enum',
    'def', 'function', 'public', 'private', 'protected', 'import',
    'from', 'export', 'module', 'typedef', 'using', 'include', 'use', 'func',
}

def initial(s):
    w = s.strip()
    if s.startswith('<|'):
        return 10.3
    if not w:
        if not s.isascii():
            return 13.0
        if '\n' in s:
            return 3.2 if s.count('\n') == 1 else 2.0
        if '\t' in s:
            return 13.4 if s == '\t' else 18.5
        n = len(s)
        if n == 1:
            return 6.6
        # Four-column indentation often leaves its last space on the word token.
        return 20 + 30 / math.sqrt(n) if n % 4 == 3 else 19.5
    if w.startswith(('"""', "'''")):
        return 9.6
    if s in {'package', 'using'}:
        return 25.3
    if s in {'public', 'private', 'protected'}:
        return 30.0
    if s in {'int', 'void', 'char', 'bool', 'float', 'double', 'long'}:
        return 23.0
    if w.startswith(('//', '/*', '<?')):
        return 10.0
    if w.startswith('#!'):
        return 8.6
    if w.startswith('#include'):
        return 10.7
    if w.startswith('#'):
        return 15.0
    if '\n' in s and not any(c.isalpha() for c in s):
        return 2.4
    if w.isdecimal():
        return 5.2 if set(w) <= set('01') else 6.8
    if regex.search(r'[\p{Script=Han}\p{Script=Hangul}]', w):
        return 5.0
    if regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', w):
        return 6.0
    if not any(c.isalpha() for c in w):
        if s == '.':
            return 3.3
        if w == ':':
            return 1.5
        if w in {'-', '/'} and not s[0].isspace():
            return 3.0
        if w in '。，、；：！？':
            return 2.5
        return 5.0
    if s[0].isspace():
        if w in {'is', 'are', 'was', 'were', 'be', 'been', 'being'}:
            return 5.2
        if w in {'and', 'or', 'but', 'that'}:
            return 5.8
        return 8.7 if w[0].isupper() else 7.7
    if w in DECLARATIONS:
        return 18.0
    if w[0].isupper():
        return 11.8 if len(w) > 1 else 9.8
    return 7.4 if len(w) <= 3 else 10.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, s, True, s[-80:]), initial(s)
    _, first, uniform, tail = carry
    uniform = uniform and s == first
    # Repeating the initial token still provides no new kind of context.
    value = initial(s) if uniform else 0.0
    if not uniform and '\\\\' in s:
        # TeX table/equation line breaks, versus escaped program text.
        tex = '\n' in s or (s.startswith(' ') and (
            '&' in tail or (regex.search(r'\\[A-Za-z]+', tail)
                            and '\\"' not in tail)))
        value = -1.4 if tex else 1.1
    return (doc, first, uniform, (tail + s)[-80:]), value

"""Approximate a sparse collection of formatting-sensitive activations.

Emit negative pulses for particular comment/markup delimiters, C includes,
template markers, PASS log lines, and web metadata phrases. Repeated middle
dots and a shell pipe followed by while get positive pulses. Other text is
zero, except for document-initial punctuation and character-class offsets.
Only the preceding two tokens are retained, resetting between documents.
This captures a small part of the component, not all its lexical variation.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prev, prev2 = ('', '') if first else carry[1:]
    value = 0.0

    if first:
        if s == '//\n':
            value = -5.13
        elif s == '\xa0':
            value = -1.85
        elif s in ('{', '{"'):
            value = -1.4
        elif s == ';':
            value = -1.06
        elif s.isdigit():
            value = -0.18
        elif s.isspace():
            value = -0.25
        elif s.startswith('_') and s[1:].isalpha():
            value = 0.6
        elif s.startswith('\\') and len(s) > 1:
            value = 0.7
        elif s.isascii() and s.isalpha():
            value = 0.29 if s[0].isupper() else 0.14
        elif s.startswith(' ') and s.strip().isascii() and s.strip().isalpha():
            value = 0.11 if s.strip().islower() else 0.0
    else:
        if s == '··' and prev == s:
            value = 0.83
        elif s == ' <!--':
            value = -4.5 if prev.strip() == '*' else -7.0
        elif prev.endswith('<!--') and s.strip() in ('begin', 'end'):
            value = -9.1 if s.strip() == 'begin' else -7.2
        elif s == '<!':
            value = -5.0 if prev == '?' else -1.8
        elif s == ' <':
            if prev.strip() in ('#include', 'include'):
                value = -1.05
            elif prev.isspace() or prev.strip() in ('*', '///', '='):
                value = -0.45
            elif len(prev.strip()) > 2:
                value = -0.18
        elif s == ' PASS' and prev.strip() == '---':
            value = -1.45 if prev.startswith(' ') else -1.0
        elif s.strip().lower() == 'updated' and prev.strip().lower() == 'last':
            value = -4.6 if s.strip() == 'Updated' else -0.8
        elif s.strip().lower() == 'more' and prev.strip().lower() == 'view':
            value = -2.5 if s.strip() == 'More' and prev == 'View' else -1.3
        elif s == ' on' and prev.strip() == 'Posted':
            value = -1.7
        elif s == 'open' and prev.endswith('\\<'):
            value = -2.0
        elif prev == '{%' and s == ' end':
            value = -1.8
        elif s == '_' and prev == '%' and prev2 == '<':
            value = -2.8
        elif s == ' if' and ((prev == '%' and prev2 == '<') or
                            (prev == '_' and prev2 == '%')):
            value = -1.5
        elif s == '%' and prev == '<':
            value = -0.8
        elif s == 'xml' and prev.endswith('<?'):
            value = -2.0
        elif s.strip() == 'eslint' and prev.strip() == '/*':
            value = -2.0
        elif s == ' while' and prev.strip() == '|':
            value = 2.0
        elif s == ' ?' and prev.strip() == '<':
            value = -1.3
        elif s == ' ---' and prev == ']':
            value = -0.5
        elif s == ' :::' and prev.isspace():
            value = -1.85
        elif re.fullmatch(r'[-~]{2,}', s.strip()):
            if prev.strip() in ('--', '/*', '#', '~'):
                value = -1.4 if prev.strip() in ('/*', '#') else -0.8
        elif s == '!' and prev == ' [':
            value = -1.8
    return (doc, s, prev), value

"""A context-sensitive detector of short, productive word beginnings.

Count common longer words extending the letters seen so far. Short beginnings
with many extensions get positive responses, especially in non-English text;
complete frequent words and later pieces get little response. Recent complete
Latin-script words estimate the language using fixed word-frequency tables.
Cyrillic and Greek fragments receive stronger responses. Document onset and
undecodable character pieces have separate baselines.
"""
import math
from collections import defaultdict
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = (
    'en', 'de', 'fr', 'es', 'it', 'nl', 'pt', 'sv',
    'da', 'nb', 'pl', 'tr', 'ru', 'el', 'fa', 'id',
)
LEXICONS = {}
for language in LANGUAGES:
    counts = defaultdict(int)
    for word in top_n_list(language, 25000):
        if word.isalpha():
            for length in range(2, min(6, len(word) - 1) + 1):
                counts[word[:length]] += 1
    LEXICONS[language] = counts


@lru_cache(maxsize=50000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


@lru_cache(maxsize=50000)
def spelling(word):
    lower = word.lower()
    count, language = max(
        (LEXICONS[lang].get(lower, 0), lang) for lang in LANGUAGES
    )
    diversity = math.log1p(count) / (1 + zipf_frequency(lower, language))
    letters = [c for c in anyascii(word).lower() if c.isalpha()]
    vowels = sum(c in 'aeiouy' for c in letters)
    ending = letters[-1] if letters else ''
    cyrillic = bool(regex.search(r'\p{Cyrillic}', word))
    greek = bool(regex.search(r'\p{Greek}', word))
    latin = bool(regex.search(r'\p{Latin}', word))
    return count, diversity, vowels, ending, cyrillic, greek, latin


def fragment_response(count, english, vowels, ending, native, native_count,
                      greek, margin):
    if english <= 3.39:
        if vowels > 1:
            return 0.09 if count <= 20 else 0.24
        if native == 0:
            if count <= 20:
                return 0.45
            if greek:
                return 0.82
            return 0.22 if ending in 'aeiouy' else 0.56
        if ending in 'aou':
            return 0.09
        if native_count <= 42:
            return 0.27 if count <= 199 else 0.49
        return 0.44 if native_count <= 220 else 0.75
    if ending in 'aeiouy':
        return -0.024
    if native > 6.63:
        return 0.05
    if margin <= 0.41:
        return 0.08
    return 0.27 if english <= 4.91 else 0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        previous, scores = '', (0.0,) * len(LANGUAGES)
    else:
        _, previous, scores = carry
    token = prefix.token_strings[-1]
    match = regex.search(r'\p{L}+$', token)
    new_word = not previous or not match or match.start() > 0
    if new_word and len(previous) >= 2:
        if regex.fullmatch(r'\p{Latin}+', previous):
            scores = tuple(0.85 * old + 0.15 * new
                           for old, new in zip(scores, frequencies(previous)))
    word = (match[0] if new_word else previous + match[0]) if match else ''
    carry = doc, word, scores
    count, diversity, vowels, ending, cyrillic, greek, latin = spelling(word)
    if initial:
        return carry, 0.42 if diversity <= 0.693 else 0.70

    margin = max(scores[1:]) - scores[0]
    profile = frequencies(word)
    english = profile[0]
    language = max(range(len(scores)), key=lambda i: scores[i])
    native = profile[language]
    native_count = LEXICONS[LANGUAGES[language]].get(word.lower(), 0)
    broken_character = '\ufffd' in token
    if margin < -0.1225:
        if cyrillic:
            if count <= 11:
                value = -0.017 if diversity <= 0.309 else 0.12
            else:
                value = 0.20 if ending in 'aeiouy' else 0.47
        elif broken_character:
            value = 0.08
        elif latin and english < 1.18 and len(word) > 4 and vowels <= 3:
            value = -0.04
        else:
            value = 0.002
    elif count <= 6:
        if len(previous) > 2:
            value = -0.01
        elif broken_character:
            value = 0.15 if margin > 0 else 0.05
        elif diversity > 0.137 and vowels <= 1:
            value = 0.35 if cyrillic else 0.13
        elif greek:
            value = 0.23
        else:
            value = 0.006
    else:
        value = fragment_response(count, english, vowels, ending, native,
                                  native_count, greek, margin)
    return carry, value

programs.haiku:
"""Layer 1 MLP slot 2961, down_proj component 2961.

In plain terms: a weak detector of foreign-language word beginnings and
pieces. It sits near zero on most tokens and rises:
  * at the first token of a document, most of all when that token is a word
    with no leading space;
  * on short Cyrillic word beginnings (a space, then 2-4 letters) that start a
    longer Russian word: " от", " из", " при", " нап", " вос". Single letters
    and common short Russian words (и, в, с, к, о, на, по, не...) stay near
    zero or go slightly negative;
  * on Greek word pieces inside a word (no leading space), and on Arabic
    pieces of either kind;
  * on the repeated middle-dot filler token "··", where it is very large.
English words, digits, code and punctuation sit near zero.

The program reads each token's script, length, whether it starts a word, and
whether it is the first token of a document. It keeps no memory beyond that.
Values are rounded group means measured on training rows, not fitted to eval.
"""

import unicodedata

READS = ()

DOC_START_WORD = 0.6  # first token is a word with no leading space
DOC_START_OTHER = 0.38  # first token is spaced, punctuation, digit, or other
DOT_FILLER = "··"
DOT_FILLER_VALUE = 1.5
# Cyrillic word beginnings (after a space), by length in letters.
CYRILLIC_WORD_START = {1: -0.02, 2: 0.27, 3: 0.39, 4: 0.22, 5: 0.12}
CYRILLIC_WORD_START_LONG = 0.04
# Short Russian words that are complete words, not word beginnings.
RUSSIAN_SHORT_WORDS = {"и", "в", "с", "к", "о", "у", "а", "я", "на", "по", "не", "со", "ко"}


def _script(text):
    """Unicode script of the first letter in `text` ('' if it has none)."""
    for ch in text:
        if ch.isalpha():
            try:
                return unicodedata.name(ch).split()[0]
            except ValueError:
                return ""
    return ""


def _cyrillic(core, new_word):
    if not new_word:
        return 0.13 if len(core) == 2 else 0.03
    if core in RUSSIAN_SHORT_WORDS:
        return -0.05
    return CYRILLIC_WORD_START.get(len(core), CYRILLIC_WORD_START_LONG)


def step(carry, prefix, upstream):
    """Stateless: the document boundary is read from the document labels."""
    text = prefix.token_strings[-1]
    core = text.strip()
    new_word = text.startswith(" ")
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        is_word = core.isalpha() and not new_word
        return None, DOC_START_WORD if is_word else DOC_START_OTHER
    if text == DOT_FILLER:
        return None, DOT_FILLER_VALUE
    script = _script(text)
    if script == "CYRILLIC":
        return None, _cyrillic(core, new_word)
    if script == "GREEK":
        return None, 0.0 if new_word else 0.2
    if script == "ARABIC":
        return None, 0.17
    return None, 0.0

programs.sol:
"""A local arithmetic-notation signal, usually negative and otherwise near zero.

Fixed response levels recognize powers, roots, pi, coefficient-letter pairs,
and arithmetic operators after variable-like letters or numbers. Spacing and
nearby formula delimiters distinguish stronger and weaker cases. Common unit
abbreviations are ignored. Carets need a plausible base; minus-letter
continuations need nearby formula marks.
Only two previous tokens and a 60-character tail are retained; document changes
reset them. This program recognizes notation, not the value of an expression.
"""
import re
import unicodedata

MATH_NAMES = {'sin', 'cos', 'tan', 'cot', 'sec', 'csc', 'log', 'ln',
             'sqrt', 'exp', 'alpha', 'beta', 'gamma', 'delta', 'theta',
             'lambda', 'mu', 'nu', 'rho', 'sigma', 'phi', 'psi', 'omega',
             'pi', 'eta', 'epsilon', 'tau'}

def is_greek(s):
    return bool(s) and all(
        'GREEK' in unicodedata.name(c, '') and c.isalpha() for c in s
    )

def is_variable(s):
    s = s.lstrip('([{+-*/^_,=')
    return len(s) == 1 and (s.isascii() and s.isalpha() or is_greek(s))


def predict(s, p, pp, history):
    c, b = (s.strip(), p.strip())
    v = b.lstrip('([{+-*/^_,=')
    prev_var = is_variable(b) and (
        p[:1].isspace() or b != v or not pp or not pp[-1].isalpha()
    )
    numeric = b.isascii() and b.isdigit()
    prev_value = int(b) if numeric and len(b) < 4 else -1
    prev_open = prev_var and (
        any(x in b for x in '([{') or pp.rstrip().endswith(('(', '[', '{'))
    )
    prev_exponent = prev_var and ('^' in b or '^' in pp)
    bare = c.lstrip('+-*/([{')
    plus = bool(re.fullmatch(r'\+(?:[a-zA-Z]{1,2}|[(){}\\]+)?', c))
    minus = bool(re.fullmatch(r'[-−](?:[a-zA-Z]{1,2}|[(){}\\]+)?', c))
    slash = c.startswith('/') and len(c) < 5
    variable = is_variable(c)
    small_word = c.isascii() and c.isalpha() and (1 < len(c) <= 3)
    digit = c.isascii() and c.isdigit()
    space = s.startswith(' ')
    fused_operand = len(c) > 1 and c[0] in '+-/*' and bare.isalpha()
    prev_index = prev_var and v.lower() in 'ijkmn'
    prev_math_name = v in MATH_NAMES
    prev_close = bool(b) and b[-1] in ')]}'
    prev_minus = b.endswith(('-', '−'))
    prev_power = bool(b) and '^' in b
    prev_digit_run = numeric and bool(pp) and pp[-1].isdigit()
    prev_decimal = numeric and pp.endswith('.')
    prev_prev_math = pp.strip() in {'+', '-', '/', '^', '*', '=', '(', '{', '}{'}
    recent_math = any(ch in history for ch in '=+^²√$\\_')

    positive = prev_value > 0
    formula = recent_math or prev_open or prev_exponent
    product = (variable or small_word) and positive

    # A coefficient immediately before pi is an implicit product.
    if c in {'π', 'pi'} and positive:
        return -3.626
    # Slash-prefixed unit abbreviations are not treated as division operators.
    if c.startswith('/') and c[1:] in {'m', 's', 'h', 'kg', 'g', 'l', 'L'}:
        return 0.0

    if minus and prev_open:
        return -4.012 if not prev_index else -6.236
    if plus and prev_var:
        if not prev_open:
            return -1.681
        return -3.674 if v.lower() != 'n' else -6.365
    if c == '²':
        return -2.165 if prev_var else -1.328
    if slash and positive:
        if not recent_math:
            if prev_digit_run:
                return -0.109
            return -1.514 if not prev_decimal else 0.028
        if prev_value > 1:
            return -1.975
        return -3.402 if not prev_digit_run else -0.882
    if product and formula:
        if not prev_prev_math:
            if space:
                return -0.092
            if prev_digit_run:
                return -0.37
            return -0.954
        if space:
            return -0.499
        if prev_value <= 1:
            return 0.309 if not fused_operand else -2.624
        return -2.635 if not fused_operand else -0.933
    if '^' in c and len(c) < 5:
        if not (prev_var or numeric or prev_close or prev_math_name):
            return -0.1
        return -1.143 if not prev_close else -0.213
    if prev_power and (variable or digit):
        return -1.058
    if c in {'√', 'sqrt'}:
        return -3.103 if c == '√' else -1.268
    if slash and prev_math_name:
        return -4.352
    if prev_minus and variable and formula:
        if not any(ch in history for ch in '=+^²√$') and not prev_open:
            return 0.0
        return -1.199
    if not (minus and prev_var):
        return -0.001 if not (slash and prev_var) else -1.369
    return -1.384 if not fused_operand else -0.149


READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p = pp = history = ""
    else:
        _, p, pp, history = carry
    s = prefix.token_strings[-1]
    value = predict(s, p, pp, history)
    return (doc, s, p, (history + s)[-60:]), value

programs.haiku:
"""Hedges and transition words that open a clause, such as 'perhaps', 'maybe',
'Alternatively', 'However', 'Therefore', 'Sometimes'. Hedges fire hardest,
especially when they float a new idea after a comma or 'so' / 'Or'; sentence-opening
transitions fire less. A ')' that closes an 'if (...)' or 'while (...)' condition
fires a little. Everything else is 0."""

READS = ()

HEDGES = {"perhaps", "maybe", "Perhaps", "Maybe"}
MEDIUM = {
    "Alternatively", "Sometimes", "Probably", "Possibly", "possibly", "Indeed", "indeed",
    "Actually", "Interestingly", "Generally", "Unfortunately", "Ultimately",
}
WEAK = {
    "Therefore", "therefore", "Moreover", "Furthermore", "Additionally", "Similarly",
    "Instead", "Hence", "However", "Thus", "thus", "Then", "Here", "First", "Finally",
    "course", "often", "sometimes", "Consequently", "Nevertheless", "Together", "Overall",
    "Currently", "Rather", "Again", "Usually", "usually", "Later", "later",
}
WEAKEST = {"then", "also", "Also", "now", "Now", "actually", "probably", "fact", "however"}
CLAUSE_END = {",", ".", "so", "So", "Or", "but", "But", "and", ":", "\n"}
CONDITIONALS = {"if", "while"}


def level(word):
    if word in MEDIUM:
        return 1.3
    if word in WEAK:
        return 0.7
    if word in WEAKEST:
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    # carry: the keyword ('if', 'while' or '') that opened each '(' still open
    stack = list(carry) if carry else []
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        stack = []  # a new document starts: forget the open brackets
    tokens = prefix.token_strings
    token = tokens[-1]
    word = token.strip()
    previous = tokens[-2].strip() if len(tokens) > 1 else ""
    value = level(word)
    if word in HEDGES:
        value = 2.9 if previous in CLAUSE_END or previous == "" else 1.7
    for ch in token:
        if ch == "(":
            stack.append(previous if previous in CONDITIONALS else "")
        elif ch == ")" and stack:
            if stack.pop() in CONDITIONALS:
                value = max(value, 0.6)
    return tuple(stack), value

"""layers.1.mlp.down_proj:2965 -- a document-opening and filler-run component.

Almost always near zero. It responds in two places:

1. The first token of each document (the model resets attention there, so the
   value depends on how that token looks). Predicted from the token's shape:
   - a NUL character: strongly negative (about -4.6, the rare largest value);
   - a digit: mildly positive (+0.15);
   - a letter or symbol with no leading space, i.e. a word fragment or code mark:
     slightly negative, more so for longer pieces (-0.1 to -0.2);
   - a letter with a leading space (a whole word): about -0.05.
2. Inside runs of the same filler token, where the same token repeats back to
   back: a carriage return "\\r" run is about -0.2, a "⎯" run about -0.55, and a
   "bbbb" run about -1.1. Everywhere else the prediction is 0.

Each rule is an average over training positions, not an exact model of the
component. Most of its variance is token-by-token detail (a few hundred tokens
each shift the value by about 0.1) that these rules do not capture.
"""
import unicodedata

READS = ()

FILLER_RUNS = {"\r": -0.2, "⎯": -0.55, "bbbb": -1.1}


def start_value(tok):
    """Activation of a document's first token, from its shape."""
    if tok[:1] == "\x00":
        return -4.6
    body = tok.lstrip()
    if not body:
        return 0.0
    cat = unicodedata.category(body[0])
    if cat == "Nd":
        return 0.15
    if cat[0] == "L":
        if tok[0] == " ":
            return -0.05
        return {1: 0.0, 2: -0.12}.get(len(body), -0.2)
    if cat[0] in "PS":
        return 0.0 if tok[0] == " " else -0.1
    return -0.05


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return (tok, 0), start_value(tok)
    prev, run = carry
    run = run + 1 if tok == prev else 0
    if run > 0 and tok in FILLER_RUNS:
        return (tok, run), FILLER_RUNS[tok]
    return (tok, run), 0.0

programs.sol:
"""A local spelling detector, not a semantic notion of cutting.

Short cut/cush-like pieces give negative values, and uw gives positive ones.
The preceding piece extends this detector across token boundaries. Longer
cut-stem tokens are weaker. A document-opening Title: has its own pulse.
"""
import unicodedata
from anyascii import anyascii

READS = ()


def spelling(text):
    """Fold case and accents; transliterate Cyrillic letters by dictionary."""
    text = unicodedata.normalize('NFKD', text.lower())
    return ''.join(anyascii(c) if 'CYRILLIC' in unicodedata.name(c, '') else c
                   for c in text if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    p, header = carry[1:] if carry and carry[0] == doc else ('', False)
    raw = prefix.token_strings[-1]
    t = spelling(raw)
    s, old = t.strip(), p.strip()
    n = len(s)
    space = t[:1].isspace()
    joined = bool(t) and not space and t[0].isalpha()
    state = (doc, t, raw == 'Title' and p in ('', '<|endoftext|>'))
    value = 6.5 if raw == ':' and header else 0.0

    if 'uw' in t and n < 6:
        value += 2.9
    if s.startswith('cush') and n < 8:
        value -= 5.4
    if 'cut' in s and n <= 4:
        value -= 1.9 if space else 4.3
    elif s.startswith('cut'):
        value -= 0.6
    if not joined:
        return state, value

    # Spellings spanning the previous piece and the current one.
    if p.endswith('u') and t.startswith('w'):
        value += 4.3
    if p.endswith(('c', 'k', 'ts')) and t.startswith('u'):
        value -= 0.3
        if t.startswith('ut'):
            value -= 2.0 if n <= 3 else 0.9
        if t.startswith('ush'):
            value -= 3.0
    if t.startswith('ut') and n < 5:
        value -= 0.2
    if t.startswith('ush') and n < 6:
        value -= 0.7
    if t.startswith('uch') and n < 6:
        value -= 0.4
    if p.endswith('ut') and t.startswith('ch'):
        value -= 2.3
    if 'u' in p[-3:]:
        if t.startswith('ch'):
            value -= 0.7
        if t.startswith(('ion', 'ition')):
            value -= 0.8

    # A short fragment's response can persist into its suffix.
    if old.endswith('ush') and len(old) <= 4:
        value -= 1.0
    if old.endswith('utch') and len(old) <= 5:
        value -= 5.0
    if old == 'cushion':
        value -= 3.1
    if old.endswith('cut') and len(old) <= 5:
        value -= 1.1
    return state, value

programs.haiku:
"""Layer 1, MLP neuron 2966 (the down_proj component 2966), as a token-level program.

It reads the MLP hidden unit that the component's input vector points at, so its activation
is that unit's value. In plain terms, it is a detector for the spelling "cut":

  * the word "cut" (cuts, cute, cushion, cush, Cut, CUT, -cut, icut) pushes it strongly
    negative, most strongly when the "cut" is glued into a longer word
    ("per|cut|aneous", "Cal|cut|ta") rather than standing alone (" cut");
  * "cutting", "cutter", "cutoff" push it only slightly negative;
  * the piece "uw" (and " uw", " UW") pushes it strongly positive;
  * other glued word pieces starting with "ut", "uc" or "cu" push it mildly negative;
  * the first token of a document is slightly positive.

Every other token gives 0. Values are in the neuron's own units.
"""

import re

READS = ()

STRONG_CUT = re.compile(r"(cut|cuts|cute|cushion|cushions|cush|icut|[-_]cut)")
MILD_CUT = re.compile(r"(cutting|cutter|cutoff)")
U_PIECE = re.compile(r"(ut|uc|cu)[a-z]*")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    glued = not token.startswith(" ")  # no leading space: continues the previous word
    doc_start = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if STRONG_CUT.fullmatch(word):
        value = -4.0 if glued else -2.0
    elif MILD_CUT.fullmatch(word):
        value = -0.5
    elif "uw" in word:
        value = 2.8
    elif glued and U_PIECE.fullmatch(word):
        value = -0.3
    elif doc_start:
        value = 0.15
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A document-opening impulse, estimated from the opening token's type.

Opening amplitudes use character format, grammatical classes, English word
frequency, and capitalized WordNet person terms. The impulse is small for
articles, prepositions and digits, larger for
content words, headings and separators. It persists through an initial run
of identical tokens; after other text arrives this approximation returns
zero, apart from a negative GitHub hostname suffix and the colon after an
opening Title label. Lexical idiosyncrasies and the small background are not
modeled.
"""
import regex
from wordfreq import zipf_frequency
import wordnet

READS = ()
ARTICLES = set('a an the'.split())
PREPOSITIONS = set('of to in on at for from with by into over under'.split())
AUXILIARIES = set(
    'am is are was were be been being have has had do does did '
    'can could may might must shall should will would'.split()
)
DEMONSTRATIVES_AND_IT = set('this that these those it'.split())
CONJUNCTIONS = set('and or but nor yet so'.split())
QUESTIONS = set('how why what when where who whom which'.split())
PRONOUNS = set('i you he she we they me him her us them my your our their'.split())


def opening_value(s):
    t = s.strip()
    if s.startswith('<|'):
        return 5.3 if s == '<|endoftext|>' else 3.1
    if not t:
        if '\r' in s:
            return 7.8
        if '\n' in s:
            return 1.45 if s.startswith(' ') else 0.0
        if '\t' in s:
            return -1.8
        return 2.67 if len(s) == 1 else 5.0
    if t.isdecimal():
        return 0.0
    if s == 'Title':
        return 9.25  # A document metadata label.
    if s in {'package', 'import', 'using', 'namespace', 'class',
             'theorem', 'function', 'from'}:
        return 4.5  # Source-file declarations.
    if '\n' in s and not any(c.isalnum() for c in t):
        return 1.0
    if len(t) > 1 and len(set(t)) == 1 and t[0] in '#^*_·/-+':
        return 7.4
    if t == '#':
        return 5.3
    if t in {'.', ','}:
        return 2.65
    if t in {'(', ')'}:
        return 0.4 if s.startswith(' ') else 3.67
    if not any(c.isalnum() for c in t):
        return 1.6
    low = t.lower()
    if low in ARTICLES:
        return -0.4
    if low in PREPOSITIONS or low in AUXILIARIES or low == 'not':
        return 0.0
    if low in DEMONSTRATIVES_AND_IT:
        return 3.0
    if low in CONJUNCTIONS:
        return 2.2
    if low in QUESTIONS:
        return 4.4
    if low in PRONOUNS:
        return 0.5
    if regex.search(r'\p{Script=Latin}', t) and t.isalpha():
        if len(t) <= 2:
            return 0.6
        if t.istitle() and 'noun.person' in wordnet.categories(low):
            return 3.5
        frequency = zipf_frequency(low, 'en')
        if frequency < 3.5:
            return 1.0  # Many rare strings are word fragments.
        return 2.2 - 0.8 * max(0.0, frequency - 4.5)
    return 1.9 if regex.search(r'\p{Script=Han}', t) else 1.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, token, True, s == 'Title'), opening_value(s)
    _, first, initial_run, title = carry
    value = 0.0
    if initial_run:
        if token == first:
            value = opening_value(s)
        elif title and s == ':':
            value = -3.95
    if s == '.com':
        hostname = b''.join(prefix.token_bytes[-5:-1])
        if hostname.endswith((b'github', b'githubusercontent')):
            value = -3.25
    initial_run = initial_run and token == first
    return (doc, first, initial_run, title), value

"""Recognize the written speech element 话/話 and its local word sense.

It is strong by itself and in conditional 的话, weaker inside other words,
and suppressed when completing 会话/会話 ('conversation/session'). Japanese
context lowers the isolated-character response. Language characters, selected
hua/huo neighbours, Korean hwa/mal, and 喝 ('drink') have smaller responses.
Paired middle dots have a negative response; unrecognized tokens predict zero.
These rules capture sharp lexical peaks, not the small background variation.
"""
from functools import lru_cache
import regex

READS = ()
KANA = regex.compile(r'\p{Hiragana}|\p{Katakana}')


@lru_cache(maxsize=8192)
def token_value(text):
    s = text.strip()
    if s == '··':
        return -1.48
    if s in ('的话', '的話'):
        return 6.8
    if '话' in s or '話' in s:
        if '电' in s or '電' in s:
            return (0.8 if '电' in s else 0.2) * (2 / len(s)) ** 2
        if s.startswith('お'):
            return 0.9
        if s.endswith('を'):
            return 2.4
        if KANA.search(s):
            return 1.2
        # Speaking of something, its topic, or referring to an utterance.
        if s in ('话说', '話說'):
            return 7.0
        if '题' in s or '題' in s:
            return 3.5
        if s.startswith(('说', '說', '谈', '談', '这', '這', '那', '一',
                         '的话', '的話')):
            return 4.0
        if s in ('话语', '話語'):
            return 3.4
        if '笑' in s or '童' in s:
            return 0.5
        return 2.0 * (2 / len(s)) ** 2
    if s in ('语', '語'):
        return 1.5
    if '语' in s or '語' in s:
        return 0.4
    # Smaller responses to goods, fire/life, change and drawing characters.
    if '货' in s or '貨' in s:
        return (1.8 if '货' in s else 2.6) / len(s)
    if s in ('火', '活'):
        return 1.25
    if s == '化':
        return 0.33
    if s in ('画', '畫'):
        return 1.3
    if s == '喝':
        return 0.7
    if s == '화':
        return 1.9
    if s == '말':
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    s = prefix.token_strings[-1].strip()
    japanese = (same_doc and carry[1]) or bool(KANA.search(s))
    previous = prefix.token_strings[-2].strip() if same_doc else ''

    if s in ('话', '話'):
        if previous.endswith(('会', '會')):
            value = 1.2  # 会话/会話: conversation, or a computing session.
        else:
            value = 8.8 if s == '话' else (6.5 if japanese else 9.3)
    elif s == '画' and previous.endswith(('計', '计', '企', '動', '动')):
        value = 0.1  # Planning and video compounds, rather than drawing.
    else:
        value = token_value(s)
    return (doc, japanese), value

programs.haiku:
"""Only the first token of each document gets a small positive activation."""
READS = ()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.09
    return None, 0.0

"""Layer 1 MLP neuron 2971 (component layers.1.mlp.down_proj:2971): a copy detector.

In plain terms: this component goes negative when the text it is reading repeats something
already seen earlier in the same document. It tracks runs of tokens. If the last two tokens
have occurred together earlier in the document, the run is a copy; the longer the copied run
(up to 6 tokens), the more negative the component gets on word-like tokens (letters, CJK
characters). Punctuation and spaces get a smaller dip, and digits are left alone. Outside
copies the component sits near zero. The first token of a document is pushed slightly
negative, since it has no context to draw on.

The predictions are hand-set magnitudes fitted by eye to the component's activations on
training text, not a lookup table. The program explains only a few percent of the variance.
"""

import unicodedata

READS = ()
MAX_COPY = 6  # longest run of tokens the program tracks


def _is_wordlike(tok):
    return any(unicodedata.category(ch).startswith("L") for ch in tok)


def _is_digits(tok):
    return tok.strip().isdigit()


def step(carry, prefix, upstream):
    ids = prefix.token_ids
    tok = prefix.token_strings[-1]
    new_document = (
        carry is None
        or prefix.position == 0
        or prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if new_document:
        # seen[n]: the n-token runs that have occurred so far in this document
        seen, k = {n: set() for n in range(2, MAX_COPY + 1)}, 0
    else:
        seen, k = carry

    # copy: length of the longest run ending at this token that occurred earlier (0 if none)
    copy = 0
    for n in range(2, MAX_COPY + 1):
        if k + 1 < n:
            break
        if tuple(ids[-n:]) in seen[n]:
            copy = n
        else:
            break
    for n in range(2, MAX_COPY + 1):
        if k + 1 >= n:
            seen[n].add(tuple(ids[-n:]))
    k += 1  # tokens so far in this document

    value = 0.002
    if k == 1:  # first token of a document
        value -= 0.036
    if copy:
        if _is_wordlike(tok):
            value -= 0.008 * copy
        elif not _is_digits(tok):
            value -= 0.011
    return (seen, k), value

programs.sol:
"""A short co/ko spelling-fragment detector.

Look in the current token and an adjoining previous token. Respond most
negatively to short co/ko fragments, particularly with b/p or v/z endings;
weaken the response for longer spellings and familiar words. Script equivalents
are normalized, but non-ASCII spellings have a separate, weaker calibration.
This approximates the spelling response, not all its contextual variation.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Relevant letter equivalents; Japanese kana already spell the syllable ko.
# Zero is included for C0-like spellings.
EQUIVALENTS = str.maketrans({
    'к': 'k', 'о': 'o', 'κ': 'k', 'ο': 'o',
    'ک': 'k', 'ك': 'k', 'و': 'o', 'こ': 'ko', 'コ': 'ko',
    'γ': 'g', 'π': 'p', 'β': 'b', 'τ': 't', 'δ': 'd',
    'μ': 'm', 'ν': 'n', 'λ': 'l', 'ρ': 'r',
    'σ': 's', 'ς': 's', 'ζ': 'z', 'φ': 'f', '0': 'o',
})
CYRILLIC_CODAS = str.maketrans({
    'в': 'v', 'б': 'b', 'п': 'p', 'с': 's', 'з': 'z',
    'м': 'm', 'н': 'n', 'р': 'r', 'л': 'l',
    'т': 't', 'д': 'd', 'г': 'g',
})
LANGUAGES = ('en', 'es', 'fr', 'pt', 'it', 'de',
             'ru', 'pl', 'nl', 'fi', 'el')


@lru_cache(maxsize=32768)
def spelling(text):
    # Softened c is not the hard c of co.
    text = text.lower().translate(str.maketrans({'ç': 's', 'č': 't', 'ć': 't'}))
    text = unicodedata.normalize('NFKD', text)
    text = ''.join(c for c in text if not unicodedata.combining(c))
    return text.translate(EQUIVALENTS)


@lru_cache(maxsize=16384)
def familiarity(text):
    return max(zipf_frequency(text, lang) for lang in LANGUAGES)


@lru_cache(maxsize=32768)
def response(token, previous):
    s, p = spelling(token), spelling(previous)
    if not s:
        return 0.001
    adjoining = bool(p and not s[0].isspace() and s[0].isalnum())
    text = (p if adjoining else '') + s
    matches = list(re.finditer('[ck]o', text))
    if not matches:
        return 0.001
    match = matches[-1]
    boundary = len(text) - len(s)
    within_token = match.start() >= boundary
    crosses_boundary = match.start() < boundary < match.end()
    tail = text[match.end():]
    coda = tail[:1].translate(CYRILLIC_CODAS)
    stop = bool(coda) and coda in 'bpcgktd'

    # Once several characters follow co, most responses are small. An o
    # arriving after a previous c/k retains more strength before a stop.
    if len(tail) > 1:
        if not stop or within_token:
            return -0.10
        if crosses_boundary:
            return -1.93 if len(tail) <= 3 else -0.48
        return -0.20

    if coda and coda in 'mnlr':
        return -0.22
    raw = (previous if adjoining else '') + token
    if any(ord(c) > 127 for c in raw):
        if within_token:
            return -0.44
        return -2.08 if crosses_boundary else -0.46

    commonness = familiarity(raw.strip())
    if commonness > 3.5:
        before = text[:match.start()].strip()
        return -1.47 if len(before) <= 2 else -0.46
    if coda and coda in 'bp':
        return -6.62 if commonness <= 1.3 else -3.02
    if coda and coda in 'vz':
        return -3.56
    return -1.97 if within_token else -2.74


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    return (document, token), response(token, previous)

programs.haiku:
"""Clause-opening discourse connectives. A word that opens a sentence or clause and
links it to what came before: contrast ("But", "Mas", "Но", "Pero"...) fires hardest;
consequence/continuation ("So", "Therefore", "Thus", "Now", "And") fires somewhat less."""

READS = ()

CONTRAST = {"but", "ale", "mas", "pero", "aber", "doch", "ma", "ama", "но", "nhưng", "dar",
            "mais", "denn", "однако", "ف", "不过", "不過", "可是", "しかし"}
CONTRAST_MILD = {"however", "though", "although", "yet", "но", "а", "и", "但", "但是"}
CONSEQUENCE = {"so", "therefore", "thus", "hence", "now", "because", "well", "like", "und", "et"}
SMALL = {"then", "wait", "also", "while"}
SENTENCE_END = set(".!?;:\n\"”“。！？；：")
COMMA = set(",，、")


def _prev(prefix):
    return prefix.token_strings[-2].rstrip() if len(prefix) > 1 else ""


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = _prev(prefix)
    after_stop = (not prev) or prev[-1] in SENTENCE_END
    after_comma = bool(prev) and prev[-1] in COMMA
    if word in CONTRAST:
        if after_stop:
            return carry, 2.6
        if after_comma:
            return carry, 1.3
        return carry, 0.3
    if after_stop and token.strip() == "So":
        return carry, 2.0
    if after_stop and token.strip() == "And":
        return carry, 1.2
    if after_stop or after_comma:
        if word in CONTRAST_MILD:
            return carry, 1.0
        if word in CONSEQUENCE:
            return carry, 1.3
        if word in SMALL:
            return carry, 0.6
    return carry, 0.0

programs.sol:
"""Approximate local spelling patterns, rather than a semantic topic.

Exposed NG/ANG fragments are negative, especially TestNG and @angular.
Word-internal NG is weaker. Split Japanese kana are positive, especially
following あ; some transliterated A+sonorant and AL+G splits are also positive.
A double-interpunct token is negative. Otherwise use a small negative baseline,
slightly lower at document starts. Track at most 60 letters of the current word,
decoding split UTF-8 characters and resetting state at document boundaries.
"""
import re
import codecs
from anyascii import anyascii
import unicodedata

READS = ()


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        word, decoder = carry[1], carry[2]
    else:
        word = ''
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
    token = prefix.token_strings[-1]
    decoded = decoder.decode(prefix.token_bytes[-1])
    core = token.strip()
    base = plain(core)
    previous = plain(word)
    romanized = anyascii(word).lower()
    joined = word + token
    value = -0.11 if carry is None or carry[0] != doc else -0.002

    if 'testng' in joined.lower():
        if 'ng' in token.lower():
            value = -10.6
    elif base.lstrip('._-') == 'ng':
        if base != 'ng':
            value = -5.5
        elif token[:1].isspace() or not word:
            value = -2.8
        elif re.fullmatch('[aeiou]+', previous):
            value = -2.2
        else:
            value = -0.3
    elif base == 'ang':
        if (base != core.lower()
                and '\u0308' not in unicodedata.normalize('NFD', core)):
            value = -3.1
        elif not token[:1].isspace() and re.fullmatch('[ao]', previous):
            value = -4.0
        else:
            value = -0.35
    elif token in ('g', 'G') and re.fullmatch('[aeiou][nm]', previous):
        value = -3.0
