        if len(word) == 1:
            return -0.5 if isolated else -0.65
        if len(word) == 2:
            return -1.7 if isolated else -0.6
        return -0.4 if isolated else -0.13

    if before.endswith('б') and current.lower().startswith(('и', 'і')):
