# Person and group nouns, whose possessive "'s" is the strongest.
PERSON_NOUNS = {
    "man", "men", "woman", "women", "child", "children", "mother", "father",
    "person", "people", "patient", "thief", "defendant", "appellant",
    "team", "company", "family", "nation", "student", "students", "soldier",
    "soldiers", "resident", "residents", "character", "photographer",
}
S_TOKENS = {"'s", "’s", "'S", "’S"}
APOSTROPHES = {"'", "’"}
NAME_S = 0.8        # "'s" after a capitalised word (a name)
NOUN_S = 1.2        # "'s" after a lowercase common noun
PERSON_S = 1.6      # "'s" after a person or group noun
PLURAL_APOS = 1.5   # bare apostrophe after a word ending in "s"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        previous = ""
    else:
        previous = prefix.token_strings[-2].strip()
    if token in S_TOKENS:
        if previous.lower() in CONTRACTION_HOSTS or not previous[:1].isalpha():
            return carry, 0.0
        if previous[:1].isupper():
            return carry, NAME_S
        if previous.lower() in PERSON_NOUNS:
            return carry, PERSON_S
        return carry, NOUN_S
    if token in APOSTROPHES and previous.isalpha() and previous.lower().endswith("s"):
        return carry, PLURAL_APOS
    return carry, 0.0

programs.sol:
"""Coarse lexical offsets at the beginning of a document.

Opening month names, code markers, the article form 'An', and typography have
large offsets. Case, spacing and English word frequency provide rough
baselines for other opening words. Uniform repetition keeps the opening
response; the second digit of opening '12' has a negative response.
Ordinary later positions get zero. Token-specific variation remains.
"""
import calendar
from wordfreq import zipf_frequency

READS = ()
MONTHS = frozenset(calendar.month_name[1:])
SHORT_MONTHS = frozenset(calendar.month_abbr[1:])
# Uppercase SQL clause/statement words, not English uses of these words.
SQL_CLAUSES = frozenset('''
SELECT FROM INSERT UPDATE DELETE JOIN WHERE
CREATE ALTER DROP TABLE INTO WITH AND OR
ORDER GROUP SET HAVING LIMIT VALUES AS
'''.split())


def opening_value(s):
    w = s.strip()
    if s.startswith('<|'):
        return -0.18
    if s == '\r':
        return -9.58
    if s == '\t':
        return -1.92
    if s == '\\t':
        return 4.76
    if not w:
        if '\t' in s:
            return 2.3 if '\n' in s else 1.3
        if '\r' in s:
            return -1.73
        if '\n' in s:
            return -0.5
        if len(s) >= 16:
            return 1.0
        return -0.45 if len(s) <= 3 else -0.15
    if w in MONTHS:
        return 1.45 if s != w else 2.45
    if w in SHORT_MONTHS:
        return 1.9 if s != w else 3.35
    if s == 'import':
        return 4.73
    if s == '#pragma':
        return -8.52
    if s in SQL_CLAUSES:
        return -4.5
    if s in ('An', ' an'):
        return 3.23 if s == 'An' else 2.43
    if w in ('Chapter', 'Section'):
        return 3.25
    if w.lower() == 'welcome':
        return 2.1
    if s.startswith('[') and s[1:2] not in ('"', "'", ']'):
        return 3.8
    if s == '<':
        return 5.13
    if s == '```':
        return 4.42
    if s == '//\n':
        return -6.53
    if s and set(s) == {'_'}:
        return -1.6 * min(len(s), 2)
    if w.isascii() and w.isalpha():
        if s == w and len(w) == 1:
            return -1.15 if w.islower() else -0.85
        frequency = zipf_frequency(w, 'en')
        if w.isupper():
            return -1.0 if s == w else -0.3
        if w.istitle():
            if s != w:
                return 0.2 if len(w) >= 7 else -0.1
            return max(-0.25, min(0.7, 0.4 * (4.4 - frequency)))
        if s != w:
            return 1.0 if frequency < 1 else -0.25
        return -0.5
    if w.isdigit():
        return -0.17
    if w[:1] in ('"', "'", '“', '‘'):
        return -0.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, 0)
    else:
        _, first, uniform, position = carry
        carry = (doc, first, uniform and token == first, position + 1)
    _, first, uniform, position = carry
    if uniform:
        value = opening_value(s)
    elif position == 1 and first == b'1' and token == b'2':
        value = -4.58
    else:
        value = 0.0
    return carry, value

"""A localizer-boundary signal, mostly in Chinese, Japanese and Korean.

Recognize a preceding locative suffix, place pronoun, or position word;
otherwise predict zero. Japanese location particles and Chinese existence,
motion and selection predicates receive negative values. A split
Chinese compound beginning with 中 ('middle/China') usually gets a positive
value: transfer compounds are strongest, interruption compounds neutral.
CC-CEDICT supplies compounds and approximate verb classes. A short byte
tail joins split spatial expressions and resets at document boundaries.
Long-range effects and small background activity are not modeled.
"""
from functools import lru_cache
import re
import regex
import cedict

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
LINKS = set('に には にも へ で では でも での から まで における '
            'に出 に対して に対する において'.split())
PRONOUNS = set('ここ そこ あそこ どこ こちら そちら どちら 何処 なか '
               'ところ どころ 哪里 哪裡 哪儿 哪兒 '
               '这里 這裡 那里 那裡'.split())
LOCALIZERS = tuple('上 下 内 內 外 里 裡 裏 間 间 '
                   '辺 邊 边 側 侧'.split())
POSITIONS = tuple('前 後 后 面 方 部 角 所 場 场 '
                  '家 店 台 村 国 國'.split())
KOREAN = set('중 위 아래 안 밖 속 앞 뒤 사이 옆 전 후 중앙 국내 상'.split())
SPATIAL_PHRASES = set('上面 下面 里面 裡面 外面 前面 后面 後面 上方 下方 '
                     '中间 中間 旁边 旁邊 周围 周圍 '
                     '中央 中心 中途'.split())
# Only Han phrases are joined across token boundaries: Japanese kana
# pronouns could otherwise spuriously match the ends of longer words.
TAIL_WORDS = {w for w in PRONOUNS if HAN.fullmatch(w[0])} | SPATIAL_PHRASES
TAIL = re.compile(
    '(' + '|'.join(sorted(TAIL_WORDS, key=len, reverse=True)) + ')$')
FUNCTION_WORDS = set('就 也 都 会 能 可 在 是 不 和 还 又 与 而 但 更 很 将 '
                     '把 被 则 才 了 跟'.split())
MOTION = re.compile(
    r'\b(exist|existence|contain|include|appear|emerge|remain|leave|hold|hang|'
    r'have|take|load|pack|store|fill|carry|put|place|install|find|discover|see|'
    r'search|select|choose|come|go|travel|'
    r'move|run|operate|obtain)\b', re.I)
VERB = re.compile(r'\bto [a-z]')

@lru_cache(maxsize=40000)
def glosses(word):
    return tuple(s for s in cedict.glosses(word) if not s.startswith('see '))

@lru_cache(maxsize=40000)
def location(word):
    word = word.strip()
    if word.endswith(('時間', '时间', '年間', '週間', '日間')):
        return 'none'
    if word.endswith('ちら'):
        return 'position'
    if word in PRONOUNS:
        return 'pronoun'
    if word in SPATIAL_PHRASES:
        return 'localizer'
    if word.endswith('中'):
        return 'middle'
    if word.endswith(LOCALIZERS):
        return 'localizer'
    if word.endswith(POSITIONS) or word in {
        'とき', '時', 'なり', 'まで', '周り', '周囲', '周围', '周圍',
        '周辺', '附近', '中央', '中心', '内部', '內部', '外部',
    }:
        return 'position'
    if word in KOREAN:
        return 'korean'
    return 'none'

@lru_cache(maxsize=40000)
def word_class(word):
    word = word.strip()
    if word in LINKS:
        return 'jp_location'
    if word == 'の':
        return 'jp_genitive'
    if word in {'は', 'が', 'を', 'も', 'や', 'と', 'です', 'であり'}:
        return 'jp_other'
    if word in {'에', '에서', '에는', '에도', '에게', '까지', '으로', '로'}:
        return 'ko_location'
    if word == '의':
        return 'ko_genitive'
    if word in FUNCTION_WORDS:
        return 'function'
    if word.startswith('的'):
        return 'attributive'
    if not word or not word[0].isalnum():
        return 'punctuation'
    if HAN.search(word):
        senses = glosses(word)
        if not senses:
            base = word.rstrip('了着著过過')
            senses = glosses(base)
            if not senses and len(word) > 1:
                senses = glosses(word[0])
        if any(MOTION.search(s) for s in senses):
            return 'existence_motion'
        if any(VERB.search(s) for s in senses):
            return 'verb'
        return 'han_other'
    return 'other'

@lru_cache(maxsize=60000)
def predict(previous, current, context=''):
    p, c = previous.strip(), current.strip()
    spatial = TAIL.search(context)
    if spatial:
        p = spatial.group(1)
    kind, grammar = location(p), word_class(c)
    if kind == 'none':
        return 0.0
    if (kind == 'middle' and grammar in {'existence_motion', 'verb', 'han_other'}
            and c and HAN.fullmatch(c[0])):
        senses = glosses('中' + c)
        if not senses and grammar == 'han_other':
            senses = glosses('中' + c[0])
        if senses:
            if any('transfer' in s for s in senses):
                return 4.8
            if any('interrupt' in s for s in senses):
                return 0.0
            return 1.5 if p in {'中', 'の中'} else 0.6
    if grammar == 'jp_location' and c in {
        'において', 'における', 'に対して', 'に対する',
    }:
        return -0.4
    if grammar == 'existence_motion' and p in SPATIAL_PHRASES:
        return -1.3
    if grammar == 'verb' and kind == 'localizer' and len(p) > 1:
        if not glosses(p):
            return -0.8
    return VALUES.get(grammar, {}).get(kind, DEFAULTS.get(grammar, 0.0))


# Values depend on grammatical roles, not on token identities.
VALUES = {
    'jp_location': {'middle': -3.3, 'localizer': -2.3,
                    'position': -1.1, 'pronoun': -2.8},
    'jp_genitive': {'middle': -3.0, 'localizer': -1.0, 'position': -0.4},
    'ko_location': {'korean': -1.3},
    'attributive': {'middle': -2.7, 'localizer': -0.95, 'position': -0.35},
    'existence_motion': {'middle': -1.9, 'localizer': -0.7,
                         'position': -0.15, 'pronoun': -3.3},
    'verb': {'middle': -0.9, 'localizer': -0.2, 'position': -0.1},
    'han_other': {'middle': -0.35, 'localizer': -0.15,
                  'position': -0.04, 'pronoun': -0.7},
    'jp_other': {'middle': 0.4, 'localizer': 0.15},
}
DEFAULTS = {'jp_location': -0.2, 'jp_genitive': 0.07,
            'ko_location': -0.4, 'ko_genitive': -0.25,
            'attributive': 0.02, 'han_other': 0.01}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = '', b''
    if carry and carry[0] == doc:
        previous, tail = carry[1:]
    raw = prefix.token_bytes[-1]
    current = prefix.token_strings[-1]
    value = predict(previous, current, tail.decode('utf-8', 'replace'))
    return (doc, current, (tail + raw)[-12:]), value

programs.haiku:
"""Locative and existential particles: a negative signal on the small words that attach
a place, a location or an existence to a phrase.

Layer 1 MLP unit 2987 writes a negative value where the text says *where* something is
or happens: Japanese locative/dative particles (に, で, へ, から, には, にも, では, でも),
Korean locative particles (에, 에서), Chinese existential or locative verbs (有, 着, 去,
没有, 包含, ...) and the attributive particle (的, の, 의). Its size is much larger when
the token just before is a place or position word (中, 里, 内, 上, 外, 面, 边, 间, 前,
下, 部, 所, 处, ところ, ここ, ...), as in "街中で", "屋内に", "体内有", "眼内有".
Everywhere else it is close to zero. The first token of a row has no context, so it gets
the average value there.

Values are least-squares fits on training rows (variance explained about 0.10 locally).
"""

READS = ()

# Words for places, locations and positions; the program checks the last character.
PLACE_WORDS = set("中里内內上外面边邊间間前下旁侧側所处處部地ころ내末")
JP_PARTICLES = {"に", "で", "へ", "から", "には", "にも", "では", "でも"}
KO_PARTICLES = {"에", "에서"}
ZH_VERBS = {"有", "着", "去", "没有", "包含", "含有", "出现", "查找", "寻找", "带着", "坐着"}
ATTRIBUTIVE = {"的", "の", "의"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.token_strings) == 1:
        # first token of a row: no context, a fixed small positive value on average
        return carry, 0.12
    prev = ""
    if prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    place = bool(prev) and prev[-1] in PLACE_WORDS
    if tok in JP_PARTICLES:
        value = -1.9 if place else -0.25
    elif tok in KO_PARTICLES:
        value = -0.9
    elif tok in ZH_VERBS:
        value = -2.9 if place else -0.2
    elif tok in ATTRIBUTIVE:
        value = -0.8 if place else 0.0
    elif place:
        value = -0.15
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A sparse multilingual character detector, mostly silent on ordinary text.

Negative responses mark connection/continuation kanji and their incomplete
UTF-8 spellings. Support/joining words are gated by recent Japanese kana.
Positive responses mark bamboo fragments, tally/signing vocabulary and some
unusual mathematical or symbol-font glyphs. Incomplete bytes are retained
only within the current document; no future character is consulted.
These rules capture selected spikes, not all ordinary-token variation.
"""
import codecs
import unicodedata
from functools import lru_cache
import unihan
import regex
import opencc

READS = ()
SIMPLIFY = opencc.OpenCC('t2s')
# Japanese kanji for introducing, continuing and connecting.
CONNECTION_LEADS = {c.encode('utf-8')[:2] for c in '紹継繋繰'}
# Support, faith/credit, friendship, joining, and knotting.
SUPPORT_AND_CONNECTION = {'支', '信', '信用', '友', '合', '结', '纽'}

@lru_cache(maxsize=4096)
def partial_family(pending):
    chars = []
    if len(pending) >= 2:
        for last in range(128, 192):
            try:
                chars.append((pending + bytes([last])).decode('utf-8'))
            except UnicodeDecodeError:
                pass
    if not chars:
        return ''
    # The low, non-letter portion of a private-use symbol-font page.
    if all(0xF000 <= ord(c) <= 0xF03F for c in chars):
        return 'symbol_font'
    if sum(unihan.radical(c) == 120 for c in chars) > .8 * len(chars):
        return 'silk'
    if sum(unihan.radical(c) == 118 for c in chars) > .8 * len(chars):
        return 'bamboo'
    names = [unicodedata.name(c, '') for c in chars]
    if sum('MATHEMATICAL' in n and 'ITALIC' in n for n in names) > .8 * len(chars):
        return 'math'
    return ''

@lru_cache(maxsize=30000)
def classify(old, token):
    decoder = codecs.getincrementaldecoder('utf-8')('ignore')
    text = decoder.decode(old + token)
    pending = decoder.getstate()[0]
    family = partial_family(pending)
    if family == 'symbol_font':
        rule = 'symbol_font'
    elif family == 'math':
        rule = 'math_italic'
    elif family == 'bamboo':
        rule = 'bamboo_split' if old else 'bamboo_prefix'
    elif family == 'silk':
        if old:
            rule = 'silk_split'
        elif pending in CONNECTION_LEADS:
            rule = 'connection_prefix'
        else:
            rule = 'other_silk_prefix'
    elif old and text == '繋':
        rule = 'connect_completion'
    elif old and text in ('紹', '継', '繰'):
        rule = 'continue_completion'
    else:
        word = SIMPLIFY.convert(text.strip())
        if word == '筹':  # A counting tally; also planning/raising funds.
            rule = 'tally_character'
        elif word.startswith('筹') and len(word) == 2:
            rule = 'tally_word'
        elif word.startswith('签') and len(word) == 2:  # Signing documents.
            rule = 'signing_word'
        elif word in SUPPORT_AND_CONNECTION:
            rule = 'support_and_connection'
        else:
            rule = ''
    kana = bool(regex.search(r'\p{Hiragana}|\p{Katakana}', text))
    return pending, rule, kana

VALUES = {
    'symbol_font': 4.5,
    'math_italic': 3.0,
    'bamboo_split': 3.8,
    'bamboo_prefix': 0.6,
    'silk_split': -1.7,
    'connection_prefix': -1.5,
    'other_silk_prefix': -0.17,
    'connect_completion': -3.6,
    'continue_completion': -1.4,
    'tally_character': 5.5,
    'tally_word': 1.4,
    'signing_word': 1.3,
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, age = carry[1:] if carry is not None and carry[0] == doc else (b'', 9)
    pending, rule, kana = classify(old, prefix.token_bytes[-1])
    value = VALUES.get(rule, 0.0)
    if rule == 'support_and_connection' and age <= 8:
        value = -0.65
    age = 0 if kana else min(age + 1, 9)
    return (doc, pending, age), value

"""A sparse predictor for mathematical group endings and completeness phrases.

Closing braces are strongest for TeX font, accent, and text groups, and weaker
for ordinary identifiers or indentation. Completeness adjectives are strongly
negative after 'a/an', but not after 'the'. Separate branches cover 'a range
of', the character 若, and repeated middle dots. All other positions predict
zero. A 180-character text buffer resets at document boundaries.
"""
import re

READS = ()
# Values for bare use, an indefinite article, 'the', and a possessive.
COMPLETENESS = {
    'whole': (-0.55, -2.6, 0.02, -0.25),
    'entire': (-1.25, -4.0, 0.23, -0.45),
    'full': (-0.45, -1.18, 0.16, -0.1),
    'complete': (-0.05, -0.65, 0.13, 0.0),
}
POSSESSIVES = set('my your his her its our their'.split())
FANCY_FONTS = set('mathbb mathcal mathscr mathfrak'.split())
OTHER_FONTS = set('mathbf mathsf mathtt'.split())
ACCENTS = set('vec hat bar tilde widetilde widehat overline dot'.split())


def brace_value(previous, recent):
    """The closing token's size depends on what sort of group it ends."""
    opening = re.search(r'\\([A-Za-z]+)\s*\{[^{}]*$', recent)
    command = opening[1] if opening else ''
    if command in FANCY_FONTS:
        return 2.3
    if command == 'mathrm':
        return 2.3
    if command in OTHER_FONTS:
        return 2.1 if len(recent.rsplit('{', 1)[-1]) == 1 else 1.3
    if command in {'text', 'mbox'}:
        return 1.7
    if command == 'operatorname':
        return 2.3
    if command in ACCENTS:
        return 1.65
    if re.search(r'\{\s*\\(?:rm|bf|it|cal)\b[^{}]*$', recent):
        return 1.55
    if re.search(r'\\[nt]$', recent):
        return 0.13
    symbol = previous.strip()
    if not symbol or previous.endswith('\n'):
        return 0.05 if recent else 0.5
    if symbol.isascii() and symbol.isdigit():
        return 1.0
    if len(symbol) == 1 and symbol.isascii() and symbol.isalpha():
        return 1.2 if symbol.isupper() else 1.0
    if symbol.startswith('_') and symbol[1:].isalpha():
        return 0.7
    if re.search(r'\\[A-Za-z]+$', recent):
        return 1.35
    return 0.55


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if recent else ''
    word, before = token.strip().lower(), previous.strip().lower()
    value = 0.0
    if token == '}':
        value = brace_value(previous, recent)
    elif token == '}}':
        value = 0.34
    elif '}' in token and not any(c.isalnum() for c in token):
        if '\n' in token or '{' in token or '`' in token:
            value = 0.02
        elif token.endswith('$'):
            value = 0.06
        else:
            value = 0.05 if token[:1].isspace() else 0.15
    elif word in COMPLETENESS:
        values = COMPLETENESS[word]
        index = (1 if before in {'a', 'an'} else 2 if before == 'the'
                 else 3 if before in POSSESSIVES else 0)
        value = values[index]
        if index == 1 and previous.strip().istitle():
            value *= 0.7
        if word == 'whole' and re.search(r'\bas a$', recent):
            value = -1.6
        if word == 'full' and before in {'in', 'at', 'of', 'to', 'for'}:
            value = -0.95
        if token.strip() != word:
            value = -0.2 if word in {'full', 'whole', 'entire'} else 0.0
    elif token == ' of' and re.search(r'\ba range$', recent):
        value = -1.1
    elif token == '若':
        value = 1.3
    elif token and set(token) == {'·'} and len(token) >= 2:
        if not recent or (previous and set(previous) == {'·'}):
            value = 1.18
    return (document, (recent + token)[-180:]), value

"""Approximate the component's strongest local spelling responses.

Greek nu after omega is negative, while sigma/tau after omega are
positive. Word length adjusts the endings -ων and -ως. Persian heh
and its endings are negative; Persian-specific letters earlier in the
document distinguish them from Arabic. Ukrainian -ів is also negative.
Other positions are predicted near zero, leaving smaller effects out.
Joined bytes handle split Unicode letters; state resets per document.
"""
import unicodedata
import regex

READS = ()
PERSIAN_LETTERS = frozenset("یکگپچژ")
GREEK_WORD = regex.compile(r"\p{Script=Greek}+$")


def unaccent(text):
    return "".join(c for c in unicodedata.normalize("NFD", text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, persian = (carry[1:] if carry is not None and carry[0] == doc
                    else (b"", False))
    raw = prefix.token_bytes[-1]
    before = old.decode("utf-8", "ignore")
    joined = (old + raw).decode("utf-8", "ignore")
    token = joined[len(before):]
    previous = before[-1:]
    persian = persian or bool(PERSIAN_LETTERS.intersection(token))
    letter, prev = unaccent(token), unaccent(previous)
    word = GREEK_WORD.search(before)
    length = min(len(word[0]), 12) if word else 0
    value = 0.0

    if letter == "ω" and length:
        value = 0.6 if token != "ω" else 1.2
        if prev == "σ":
            value = 2.4
    elif prev == "ω":
        if letter == "ν":
            value = -2.9 - 0.28 * length
        elif letter == "ς":
