quantity words. It fires hardest on "some", less on "any", and on the "of" in "a lot of",
"plenty of", "a bit of", "a piece of". It fires weakly on "sum" and "summer" (spelling close
to "some"). It is near zero on other words, including "something", "someone" and "anything".

How strongly "some" and "any" fire depends on the word before them. As the object of a
verb, or after "with"/"without", ("have some", "didn't have any", "with some") they fire
hardest. After a preposition, conjunction or punctuation ("in some", "for any", ", some")
they fire least. Other positions sit in between.
"""

READS = ()

# Words after which "some"/"any" is the object of a verb, as in "have some".
OBJECT_CUES = {
    "have", "has", "had", "having", "get", "got", "see", "find", "found", "make", "made",
    "do", "did", "give", "gave", "take", "took", "need", "use", "using", "want", "include",
    "create", "put", "set", "add", "try", "offer", "provide", "buy", "eat", "drink", "be",
    "been", "with", "without",
}
# Words after which "some"/"any" starts a prepositional or clause-level phrase.
LEAD_IN_CUES = {
    "in", "for", "at", "that", "and", "or", "as", "if", "but", "are", ",", ".",
}
# Measure nouns that take "of": "a lot of", "plenty of", "a bit of".
STRONG_MEASURE_NOUNS = {"lot", "lots", "plenty", "bit"}
MEASURE_NOUNS = STRONG_MEASURE_NOUNS | {
    "deal", "bunch", "ton", "tons", "piece", "pieces", "ounce", "ounces", "spot", "handful",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2].strip().lower()
    if word == "some":
        value = 5.2 if before in OBJECT_CUES else 2.0 if before in LEAD_IN_CUES else 3.2
    elif word == "any":
        value = 2.7 if before in OBJECT_CUES else 0.9 if before in LEAD_IN_CUES else 1.2
    elif word == "of" and before in STRONG_MEASURE_NOUNS:
        value = 4.3
    elif word == "of" and before in MEASURE_NOUNS:
        value = 2.5
    elif word in ("sum", "summer"):
        value = 1.2
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Recognize completions of conventional phrases, especially 'X of Y'.

Dictionary compounds containing 'of' get a moderate negative response. The groups
below mark expressions with particularly large responses in training. Hyphens and
underscores count as word separators, so identifiers work too. A separate rule
handles numerical separators (especially after digits 1–3), square roots
and 2π.
These are approximations, not a full account of context-dependent strength.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

STRONG_EXPRESSIONS = {
    'word of mouth', 'line of sight', 'right of way',
    'peace of mind', 'order of magnitude', 'depth of field',
    'quality of service', 'power of attorney',
    'terms of service', 'denial of service', 'standard of living',
}
MEDIUM_EXPRESSIONS = {
    'place of birth', 'date of birth', 'year of birth',
    'quality of life', 'table of contents', 'internet of things',
    'rate of change',
}

@lru_cache(maxsize=16384)
def expression_value(words):
    phrases = [
        ' '.join(words[-n:]) for n in (4, 3)
        if len(words) >= n and 'of' in words[-n:]
    ]
    if any(p in STRONG_EXPRESSIONS for p in phrases):
        return -9.0
    if any(p in MEDIUM_EXPRESSIONS for p in phrases):
        return -5.2
    if 'code of conduct' in phrases:
        return -6.6
    if any(wordnet.parts_of_speech(p) for p in phrases):
        return -1.4
    return 0.0


@lru_cache(maxsize=4096)
def bare_noun(word):
    return 'noun' in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    text = (before + token)[-100:]
    normalized = re.sub(r'[_-]', ' ', text.lower())
    words = tuple(re.findall(r'[a-z]+', normalized))
    value = 0.0
    # Also recognize a word assembled over several BPE tokens.
    if word.lstrip('-').isalpha() and 'of' in words[-4:-1]:
        value = expression_value(words)
        if not value and re.search(r'\bof\s*$', before, re.I):
            value = -0.07 if bare_noun(word) else 0.0
    if words[-3:] == ('all', 'the', 'way') and word == 'way':
        value = -6.1
    if words[-3:] in (('call', 'to', 'action'), ('calls', 'to', 'action')):
        if word == 'action':
            value = -5.5
    if len(word) == 1 and word in '0123456789':
        match = re.search(r'([1-3])\s*([-–+,/:])\s*$', before)
        if match and int(word) >= 2:
            separator = match[2]
            if separator == '+':
                value = 1.4
            elif separator in '-–':
                value = 0.75
            elif separator == ',':
                value = 0.33
            elif separator == '/':
                value = -0.3
        elif int(word) >= 2 and re.search(r'\d\s*\+\s*$', before):
            value = 0.45
        if re.search(r'(√|sqrt)\s*$', before):
            value = -0.6
    if word == 'π' and before.endswith('2'):
        value = -2.5
    return (doc, text), value

programs.haiku:
"""Idiom-completion detector: layers.1.mlp.down_proj, component 3001.

The component goes negative on the word that finishes a fixed phrase, the word a
reader can predict from the words before it:
"peace of [mind]", "order of [magnitude]", "date of [birth]", "cost of [living]",
"depth of [field]", "word of [mouth]", "right of [way]", "League of [Legends]",
"Call of [Duty]", "power of [attorney]", "line of [sight]", "terms of [service]",
"all the [way]", and words split across tokens, as in "[con][duct]".
It also fires on hyphenated forms ("rights-of-[way]", "point-of-[care]").
After "of" followed by an ordinary word ("of the", "of two", "of many") it stays near 0.

The program is a small lexicon, with three rules:
  1. The word right after "of" (or "-of"): if it is one of the nouns below, predict a
     negative value, stronger for phrases that are nearly always fixed.
  2. "way" after "all the": "all the way" is reliably strongly negative.
  3. "duct" right after "con": the split word "conduct" (as in _CONDUCT).
Every other position predicts 0. The program reads only the current token and the
few before it, within the same document.
"""

READS = ()

# Typical activation, by how fixed the phrase is.
STRONG = -8.0  # nearly always a fixed phrase: order of magnitude, right of way, word of mouth
MIDDLE = -5.0  # usually fixed: date of birth, peace of mind, line of sight, cost of living
WEAK = -1.5  # often a fixed phrase, often not: state of, law of, death of, life of
ALL_THE_WAY = -6.0  # "all the way"
CON_DUCT = -6.0  # the second half of a split "conduct" (con | duct)

STRONG_WORDS = {"magnitude", "way", "mouth", "legends", "attorney", "field"}
MIDDLE_WORDS = {
    "birth", "concept", "flight", "action", "squares", "contents", "living", "mind",
    "sight", "service", "view", "duty", "return", "care",
}
WEAK_WORDS = {
    "life", "death", "freedom", "interest", "god", "government", "law", "state",
    "business", "things", "war", "appeals", "year", "day", "motion", "change",
}


def _word(text):
    """A token's word: lower case, without the space or hyphen it starts with."""
    return text.strip().lstrip("-_").lower()


def _of_strength(word):
    """Activation of a word that follows "of"."""
    if word in STRONG_WORDS:
        return STRONG
    if word in MIDDLE_WORDS:
        return MIDDLE
    if word in WEAK_WORDS:
        return WEAK
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    if t < 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before, word = _word(prefix.token_strings[-2]), _word(prefix.token_strings[-1])
    if before == "of":
        return carry, _of_strength(word)
    if before == "con" and word == "duct":
        return carry, CON_DUCT
    if word == "way" and before == "the" and t >= 2:
        same_doc = prefix.document_ids[-3] == prefix.document_ids[-1]
        if same_doc and _word(prefix.token_strings[-3]) == "all":
            return carry, ALL_THE_WAY
    return carry, 0.0


if __name__ == "__main__":
    # Quick check on a phrase: "birth" in "date of birth" is about -5.
    class _P:
        position = 2
        document_ids = [0, 0, 0]
        token_strings = ["date", " of", " birth"]

    print(step(None, _P, {})[1])  # -5.0

programs.sol:
"""A shallow preverbal-adverb detector.

Adverbs inserted after a subject produce a large negative response; modals
and perfect auxiliaries give a smaller response, and forms of 'be' a weaker
one. Small positive activations are not modeled. WordNet is used to
handle ambiguous nouns and verbs, rather than a token lookup table.
It also covers floating quantifiers, intensifiers, and compound adverbials.
A small set of translated negation/addition/time expressions is recognized
without attempting to parse the other languages.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
SUBJECTS = set('i you he she it we they who which'.split())
MODALS = set('can could may might must shall should will would'.split())
BE = set("am is are was were be been being 'm 's 're ’m ’s ’re".split())
HAVE = set("have has had 've ’ve 'd ’d".split())
DO = set('do does did'.split())
DETERMINERS = set('a an the my your his her its our their every some any no'.split())
DEMONSTRATIVES = set('this that these those'.split())
FUNCTION = set((
    'and or but nor so if when where while because although as than for of in on '
    'at by with without from into over under until since to not after before '
    'about through between around during within among against off'
).split())
TIME = set('now still already yet soon recently currently once again'.split())
SEQUENCE = set('then later eventually finally previously subsequently'.split())
FREQUENCY = set((
    'always never ever often usually sometimes seldom rarely frequently '
    'occasionally generally typically normally routinely'
).split())
FOCUS = set('only just even merely simply'.split())
CERTAINTY = set((
    'likely probably certainly possibly perhaps maybe surely clearly apparently '
    'obviously'
).split())
CONSEQUENCE = set('therefore thus hence consequently accordingly'.split())
FLOATING_MODIFIERS = set('all both each either neither itself themselves'.split())
ORDERING = set('first last next early'.split())

PREPOSITIONS = set('of for with in on at by from to'.split())

@lru_cache(maxsize=20000)
def pos(word):
    return wordnet.parts_of_speech(word)


# Pool related adverb classes to keep the response table small.
ADVERB_FAMILIES = (
    ('additive', set('also additionally further moreover furthermore'.split())),
    ('temporal', TIME | FREQUENCY | ORDERING),
    ('sequence', SEQUENCE | CONSEQUENCE),
    ('focus', FOCUS | CERTAINTY | FLOATING_MODIFIERS),
    # Other -ly adverbs and stance words share one magnitude scale.
    ('manner', set('really actually indeed hereby however nevertheless'.split())),
)


def family(word):
    if word in ("not", "'t", '’t'):
        return 'negation'
    for name, words in ADVERB_FAMILIES:
        if word in words:
            return name
    if word.endswith('ly') and 'adverb' in pos(word):
        return 'manner'
    return None


def context(words):
    """Return the grammatical environment and confidence in a nominal reading."""
    prev = words[-1] if words else ''
    p = prev.lower()
    before = words[-2].lower() if len(words) > 1 else ''
    if p in SUBJECTS:
        if before in MODALS | HAVE | BE | DO:
            return ('be' if before in BE else 'modal'), 1.0
        if (p in {'it', 'you'}
                and (before in PREPOSITIONS or 'verb' in pos(before))):
            if before not in {'if', 'when', 'because', 'that', 'and', 'but'}:
                return 'other', 0.2
        return 'subject', 1.0
    if p in MODALS:
        return 'modal', 1.0
    if p in HAVE:
        return 'have', 1.0
    if p in BE:
        return 'be', 1.0
    if p in DO:
        return 'do', 1.0
    if p in DEMONSTRATIVES:
        return 'demonstrative', 1.0
    if p in DETERMINERS:
        return 'other', 0.0
    if not p or not p[-1:].isalpha():
        return 'other', 0.0
    if p in FUNCTION:
        return 'other', 1.0
    if p in {'see', 'read', 'look', 'refer'}:
        return 'other', 0.1
    tags = pos(p)
    if (p.endswith(('ed', 'ing'))
            and not ('noun' in tags and before in DETERMINERS)):
        return 'other', 0.2
    if prev[:1].isupper():
        confidence = 1.0
    elif 'noun' in tags:
        confidence = 0.7 if 'verb' in tags else 1.0
    else:
        return 'other', 1.0
    if before in SUBJECTS or before in PREPOSITIONS:
        confidence *= 0.35
    return 'nominal', confidence


def event(tail, token):
    match = re.search(r"([A-Za-z]+|['’]t)$", token)
    if not match:
        return None
    word = match.group().lower()
    preceding = tail + token[:match.start()]
    if match.start() == 0 and word[0].isalpha() and tail[-1:].isalpha():
        m = re.search(r'[A-Za-z]+$', tail)
        if m:
            word = m.group().lower() + word
            preceding = tail[:m.start()]
    preceding = preceding.replace('\\n', '\n').rsplit('\n', 1)[-1]
    words = re.findall(r"[A-Za-z]+|['’][A-Za-z]+|[^\w\s]", preceding)
    prev = words[-1].lower() if words else ''
    fam = family(word)
    compound = False
    if word == 'only' and prev == 'not':
        words = words[:-1]
    # These phrases, like single-word adverbs, can intervene before a verb.
    if (word, prev) in {('turn', 'in'), ('longer', 'no'),
                       ('of', 'kind'), ('of', 'sort')}:
        fam = 'sequence'
        compound = True
        words = words[:-1]
        if word == 'of' and words and words[-1].lower() in DEMONSTRATIVES:
            return None
    if fam is None:
        return None
    if word in ("'t", '’t'):
        return 'contraction', 'other', 1.0
    if word == 'also' and prev == 'see':
        return None
    env, confidence = context(words)
    if fam != 'negation':
        if env == 'demonstrative':
            env = 'subject' if fam == 'additive' else 'nominal'
        if env == 'nominal':
            if word in ORDERING | FLOATING_MODIFIERS:
                confidence *= .5
            if compound:
                confidence *= 2
        if env in {'modal', 'have'}:
            env = 'auxiliary'
        elif env == 'do':
            env = 'be'
    return fam, env, confidence


# Typical magnitudes by adverb family and grammatical environment.
COLUMNS = ('subject', 'nominal', 'auxiliary', 'be', 'other')
RESPONSES = {
    'additive': (4.01, 3.36, 1.43, 0.71, 0.34),
    'temporal': (3.24, 1.26, 1.00, 0.26, 0.23),
    'sequence': (4.89, 1.08, 1.22, 0.33, 0.09),
    'focus': (3.72, 1.00, 1.19, 0.21, 0.08),
    'manner': (2.85, 0.72, 0.74, 0.05, 0.14),
}
NEGATIVE = {
    'subject': .49, 'nominal': .17, 'modal': .62, 'have': .74,
    'be': .61, 'do': .95, 'demonstrative': .04, 'other': .15,
}

FOREIGN = (
    # Negation, addition, and temporal/aspectual adverbs, grouped by meaning.
    (set('не nie nicht pas không'.split()), -.7),  # not
    (set('não inte nunca لم'.split()), -1.7),  # not / never
    (set('также тоже también também cũng'.split()), -1.6),  # also / too
    (set('уже já'.split()), -1.5),  # already
    (set('也 亦 又'.split()), -1.1),  # also / again
    (set('还 還 仍 仍然 依然'.split()), -1.5),  # still / yet
    (set('真的 果然 居然 竟然 不仅 不僅'.split()), -1.3),  # indeed / not only
    (set('分别 分別 先后 先後'.split()), -1.6),  # separately / successively
    (set('则 則 却 卻'.split()), -.6),  # then / but
    (set('已经 已經 终于 終於'.split()), -1.0),  # already / finally
)
FRENCH_HINTS = set('le la les des du une pour dans avec'.split())
FRENCH_SUBJECTS = set('je tu il elle nous vous ils elles qui ce cela'.split())


def foreign_value(tail, token):
    word = token.strip().lower()
    if word == 'also':
        words = set(re.findall(r'[^\W\d_]+', tail.lower()))
        if len(words & {'und', 'der', 'die', 'das', 'ist', 'nicht', 'ich', 'zu'}) >= 2:
            return 0.0  # German 'also' is not English additive 'also'.
    for words, value in FOREIGN:
        if word in words:
            return value
    if (word in {'n', 'ne', 'non', 'no'} and token[:1].isspace()
            and token.strip().islower()):
        words = re.findall(r'[^\W\d_]+', tail.lower())
        prev = words[-1] if words else ''
        if word in {'n', 'ne'}:
            if prev in FRENCH_SUBJECTS:
                return -3.8
            if len(set(words) & FRENCH_HINTS) >= 2:
                return -1.9
        if word == 'non' and set(words) & {'che', 'gli', 'della', 'per', 'nel', 'una'}:
            return -1.8
        if word == 'no' and set(words) & {'el', 'una', 'que', 'los', 'las', 'del', 'pero'}:
            return -1.6
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = foreign_value(tail, token)
    if value is None:
        found = event(tail[-80:], token)
        value = 0.0
        if found:
            fam, env, confidence = found
            if fam == 'contraction':
                value = -.53
            elif fam == 'negation':
                value = -NEGATIVE[env] * confidence
            else:
                value = -RESPONSES[fam][COLUMNS.index(env)] * confidence
    return (doc, (tail + token)[-100:]), float(value)

"""Approximate pulses for references to nearby text, math displays, and labels.

References such as 'the following', 'as follows', 以下 and 下記 are
negative, with context-dependent strengths. Numbered East Asian labels,
page navigation, orphan initial periods, and middle-dot leaders are positive.
Everything else is
zero. An 80-character tail supplies context and resets at document boundaries.
This captures selected strong patterns, not the weaker background activity.
"""
import re

READS = ()
NUMBER = r'[\d一二三四五六七八九十百千零〇壱弐参]+'
SELECTION = {'any', 'one', 'all', 'each', 'which', 'none', 'some', 'most',
             'many', 'several', 'both'}
TEMPORAL = {'in', 'during', 'over', 'for', 'through', 'within', 'into', 'at'}
PREPOSITIONS = {'as', 'from', 'of', 'with', 'to', 'by', 'per', 'under'}
# Episode, element, part, generation and ordinal-number labels.
NUMBERED = {'集': 4.9, '要素': 4.5, '部': 2.4, '世': 2.0, '番': 1.5}
# LaTeX environment opening and closing pulses.
DISPLAYS = {'equation': (-7.4, -4.1), 'align': (-3.3, -1.3),
            'aligned': (-1.4, 0.0), 'cases': (-1.5, 0.0),
            'lemma': (-1.8, 0.0), 'theorem': (-1.8, 0.0),
            'proposition': (-1.8, 0.0), 'corollary': (-1.8, 0.0)}


def predict(token, before):
    word = token.strip()
    low = word.lower()
    words = re.findall(r'[A-Za-z]+(?:-[A-Za-z]+)?', before[-40:])
    prev = words[-1] if words else ''
    p = prev.lower()
    prior = words[-2] if len(words) > 1 else ''
    p2 = prior.lower()
    p3 = words[-3].lower() if len(words) > 2 else ''

    if low == 'following':
        if prev == 'The':
            return -1.4
        if prev == 'the':
            if prior == 'In':
                return -0.8
            if p2 in TEMPORAL:
                return -2.0
            if p2 == 'of':
                return -0.1 if p3 in SELECTION else -2.6
            if prior and prior[0].isupper():
                return -1.7
            if p2 in {'by', 'with', 'using', 'use', 'uses', 'obtain',
                      'obtained', 'get', 'satisfy', 'under'}:
                return -4.1
            return -3.0
        if p in {'a', 'any', 'these', 'this'}:
            return -1.0
        if p in {'with', 'contains', 'use', 'see'}:
            return -3.0
    if low == 'above':
        if p == 'the':
            return -2.6
        if p in PREPOSITIONS:
            return -1.6
    if low == 'below':
        if p in PREPOSITIONS | {'the', 'this', 'on', 'in'}:
            return -1.9
        if p in {'use', 'find'}:
            return -5.1
        if p in {'figure', 'table', 'steps', 'example', 'format', 'shown', 'forth'}:
            return -1.1
    if low == 'follows' and p == 'as':
        return -1.4
    if low == 'side' and p in {'left', 'right'}:
        return -1.6 if p == 'left' else -0.8
    if low in {'is', 'are'} and p in {'above', 'below', 'following'}:
        return -1.1
    if low in {'lemma', 'theorem', 'proposition', 'formula', 'conditions',
               'exception'} and p in {'following', 'above', 'below', 'last'}:
        return -2.3

    if word == '以下':
        if re.search(NUMBER + r'(?:[℃%岁倍元年個期]|公里)?$', before):
            return 0.0
        if (not before or before[-1].isspace() or before[-1] in '。，！（(:~'
                or before.endswith(('价格', '價格', '年期', '温度', '年龄'))):
            return -1.6
        return -6.6
    if word == '下面':
        return -5.7 if before.endswith(('从', '從', '满足', '滿足')) else -1.2
    if word in {'如下', '上述', '以下几个', '以下の'}:
        return {'如下': -3.6, '上述': -2.4,
                '以下几个': -3.4, '以下の': -4.3}[word]
    if word == '記' and before.endswith(('下', '上')):
        return -9.5 if before.endswith('下') else -3.3
    if word in {'のような', 'のように'} and before.endswith('以下'):
        return -5.9
    if word in {'こう', 'こんな'}:
        return -1.3
    if word in {'gende', 'genden', 'gender', 'gendes'} and prev in {'fol', 'Fol'}:
        return -3.5 if prev == 'fol' else -1.0
    if word and re.search(r'следующ[а-яё]*$', before + word):
        return -1.5

    display = re.search(r'(begin|end)\{([a-z]+)$', before + word)
    if display and display[2] in DISPLAYS:
        return DISPLAYS[display[2]][display[1] == 'end']
    if word in NUMBERED and re.search(NUMBER + '$', before):
        return NUMBERED[word]
    if word == '集' and before.endswith(('全', '本')):
        return 2.1
    if word == '一页' and before.endswith(('上', '下')):
        return 2.1
    if token == '··' and before.endswith('··'):
        return 1.3
    if not before and token == ' .':
        return 4.2
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, (before + token)[-80:]), predict(token, before)

programs.haiku:
"""Draft 5: deictic pointer words ('the following', 'the above', '以下'), scaled to half the
harvest magnitudes (on eval they fire much less than the harvest windows suggest), plus the
Chinese episode marker 集 after 第N, which is a large positive."""
READS = ()

POINTERS = {
    " following": -1.5, " above": -1.25, " follows": -0.75, " below": -0.5,
    " foregoing": -0.5, "以下": -1.5, "下面": -0.5, "如下": -1.0, "上述": -1.0,
    " side": -0.75,
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if word in POINTERS:
        return None, float(POINTERS[word])
    if word == "集" and "第" in "".join(prefix.token_strings[-5:-1]):
        return None, 2.0
    return None, 0.0

programs.sol:
"""Approximate possessive endings, code assignments, and an initial title field.

Lowercase possessors receive a stronger negative signal than capitalized
ones (capitalization is only a proxy for names). Contractions are kept near
zero. The rules also recognize plural possessives and escaped apostrophes,
while attempting to exclude closing quotation marks.

Assignment signs respond most to declarations and isolated variable names,
less to member updates, and little to recognizable arithmetic. A colon
immediately after document-initial 'Title' has a large positive response.
Other tokens receive zero; miscellaneous lexical effects are not modeled.
The carry keeps only 400 characters of the current document.
"""
import re

READS = ()
CONTRACTIONS = {
    'it', 'that', 'there', 'here', 'what', 'who', 'where', 'when',
    'how', 'why', 'he', 'she', 'let', 'this',
}
CODE = re.compile(r'\b(?:const|let|var|int|float|double|def|import|'
                  r'return|function|self|this)\b|[;{}]|'
                  r'\b(?:input|print|range|len|open|map|list|set)\(|->|::')
WORD = re.compile(r'([A-Za-z_][A-Za-z_0-9]*)$')
APOSTROPHE_ENTITY = re.compile(r'&(?:#0*39|#x0*27|#8217|apos|rsquo);?$', re.I)


def possessive(word):
    lower = word.lower()
    if lower in CONTRACTIONS:
        if lower == 'that':
            return 0.10
        if lower in {'he', 'she', 'here', 'who'}:
            return -0.08
        return 0.0
    if len(word) <= 1:
        return -0.10 if word else 0.0
    if lower in {'men', 'women', 'children'}:
        return -0.50
    return -0.58 if word[0].isupper() else -0.93


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ':' and before == 'Title':
        value = 9.45
    elif token.lower() in {"'s", '’s', 's', ';s'}:
        base = None
        if token.lower() in {"'s", '’s'}:
            base = before
        elif token.lower() == 's':
            decoded = re.sub(r'\\xe2\\x80\\x99|\\u2019|\\u0027', "'", before)
            base = re.sub(r"\s*\\?['’]\s*$", '', decoded)
            if base == decoded:
                base = None
        entity = APOSTROPHE_ENTITY.search(before)
        if entity:
            base = before[:entity.start()]
        if base is not None:
            match = WORD.search(base.rstrip())
            value = possessive(match[1] if match else '')
            if not match and base.endswith((')', ']')):
                value = -0.60
    elif token in {"'", '’', "\\'"}:
        match = WORD.search(before)
        word = match[1] if match else ''
        quoted = re.search(r"(?:^|[\s(\[=,:])\\?['‘][^'’\n]*$", before)
        if len(word) > 2 and word.endswith('s') and not quoted:
            value = -1.0 if word[0].isupper() else -1.30
    elif token in {' =', ' :=', ' <-'}:
        match = WORD.search(before)
        if match:
            name = match[1]
            line = re.split(r'\n|\\n', before)[-1]
            if token == ' <-':
                value = -0.85
            elif token == ' :=':
                value = -0.70
            elif re.search(r'\b(?:const|let|var)\s+', line):
                value = -0.80 if len(name) > 1 else -0.45
            elif re.search(
                r'\b(?:int|float|double|bool|string|String|char|auto)\s+', line
            ):
                value = -0.55
            elif re.search(r'\b(?:this|self)\.', line):
                value = -0.29
            elif re.search(
                r'\b(?:sin|cos|theta|alpha|beta|pi|mu|sigma)\b', before[-60:]
            ):
                value = 0.0
            elif re.fullmatch(r'\s*\$?[A-Za-z_][A-Za-z_0-9]*', line):
                if len(name) > 1:
                    value = -0.68
                elif CODE.search(before[-250:]) or line.startswith((' ', '\t')):
                    value = -0.55
            elif re.search(r'[A-Za-z_0-9]+[_A-Z][A-Za-z_0-9]*$', before):
                value = -0.45
            elif len(name) == 1:
                value = -0.20 if CODE.search(before[-150:]) else 0.0
            else:
                value = -0.50 if CODE.search(before[-150:]) else -0.07
    return (doc, (before + token)[-400:]), value

programs.haiku:
"""layers.1.mlp.down_proj:3004, a mostly-negative feature for possessive markers and
variable assignments.

When this component is strongly active, it is negative, and it is negative at:
  1. a possessive "'s" or "’s" after a noun ("the nation's", "each other's"), about -0.75;
     after a contraction host ("that's", "it's", "let's", "there's") it stays near 0;
  2. a possessive apostrophe after a plural noun ending in "s" ("Veterans'", "soldiers'"),
     about -0.95;
  3. the "=" of a code assignment to a variable name: -0.65 after a declaration keyword
     ("let count ="), -0.55 at the start of a statement ("result ="), -0.3 elsewhere
     after a word, about -0.1 inside a call's argument list ("f(key=...)"), and 0 after
     an attribute ("self.x =") or a closing bracket;
  4. ":=" about -0.5.
Everything else predicts 0. Predictions are in activation units.

Main program: find the newest token, decide which of the cases above it is, and return
the matching value. Only the current token and the text before it on its line are read.
"""

READS = ()
APOS = ("'", "’")
# words after which "'s" is a contraction ("that's", "it's", "let's"), not a possessive
CONTRACTION_HOSTS = {"it", "that", "there", "here", "he", "she", "let", "what", "where",
                     "who", "how", "this", "when", "why", "we", "you", "they", "i"}
DECL_WORDS = {"let", "var", "const", "int", "char", "float", "double", "long", "final",
              "val", "auto", "my", "local", "bool", "unsigned", "return", "new", "static"}


def is_word(s):
    return s.strip().isalpha()


def line_before(s):
    """Text on the current line before the newest token."""
    parts = []
    for x in reversed(s[:-1]):
        if "\n" in x:
            parts.insert(0, x.split("\n")[-1])
            break
        parts.insert(0, x)
    return "".join(parts)


def step(carry, prefix, upstream):
    s = prefix.token_strings
    tok = s[-1]
    prev = s[-2].strip() if len(s) > 1 else ""
    # possessive 's after a noun: "the nation's", "each other's"; not "that's", "it's"
    if tok in ("'s", "’s"):
        if is_word(prev) and prev.lower() not in CONTRACTION_HOSTS:
            return None, -0.75
        return None, 0.0
    # possessive apostrophe after a plural noun: "Veterans'", "the soldiers'"
    if tok in APOS and is_word(prev) and prev.endswith("s"):
        return None, -0.95
    if tok == " :=":
        return None, -0.5
    # assignment "=" to a variable name in code
    if tok == " =" and (is_word(prev) or prev.isdigit()):
        before = line_before(s)[: -len(s[-2])] if len(s) > 1 else ""
        words = before.split()
        if before.count("(") > before.count(")"):
            return None, -0.1      # keyword argument inside a call
        if not words:
            return None, -0.55     # statement starts with the name: "result ="
        if words[-1] in DECL_WORDS:
            return None, -0.65     # declaration: "let count ="
        if words[-1].endswith("."):
            return None, 0.0       # attribute: "self.x ="
        return None, -0.3
    return None, 0.0

programs.sol:
"""A local cue for relating, joining, or contrasting several things.

Predict negative activity on 'between', 'both', joining/comparing verbs,
and the 'of' introducing a mixture, arithmetic operation, or relationship.
The first article after a relation is a weaker cue. A few translations are
recognized too. 'Common ratio' is a separate, positive mathematical cue.
These are approximate phrase rules, not a complete semantic analysis.
"""
import re

READS = ()

# Translations of 'between'. Italian needs context: tra/fra can also be
# the beginning of an unrelated word, or a preposition in another language.
BETWEEN = {
    'between': -4.65, 'entre': -6.0, 'zwischen': -5.7,
    'между': -5.8, 'між': -5.8, 'między': -5.8,
    'mellom': -7.0, 'giữa': -6.0, 'بين': -6.5,
}
ITALIAN = set('''il lo gli della delle del di dei degli che nel nella
    non si'''.split())
MIXTURES = set('''mix mixture blend union intersection fusion convolution
    amalgamation concatenation mingling superposition interdependence interplay'''.split())
OPERATIONS = set('''combination mixing blending collision coupling convergence
    interconversion combining equivalence quotient multiplication'''.split())
RELATIONS = set('''comparison connection separation correlation interaction
    similarity alignment harmony interface marriage collaboration meeting'''.split())
MEASURES = set('''relation relationship proximity distance balance overlap
    coexistence exchange distribution agreement conflict association'''.split())
COLLECTIONS = set('''collection array set group list sequence series network
    system tuple plurality assortment ensemble batch'''.split())
COMPOSITION = set('''consist consists consisted consisting composed comprised
    synthesis integration merger'''.split())
PATHS = set('''path edge arrow route journey range period interval gradient
    transition conversion mapping distance equidistant difference deviation
    go going goes run running runs start starting ranging ranges map maps
    segment vector line road move moves moving travel travels transformation
    transfer shift switch switches flow flows extend extends'''.split())


def verb_value(word):
    """Surface forms distinguish active joining from weaker relatedness."""
    if word in ('connecting', 'combining', 'linking', 'connects', 'combines'):
        return -3.55
    if word in ('separates', 'balances', 'balancing', 'swap', 'swaps'):
        return -1.9
    if word == 'combine':
        return -2.9
    if re.fullmatch(r'(?:inter)?connect|compar(?:e|es|ing)', word):
        return -1.7
    if re.fullmatch(r'connect(?:ed)|combin(?:ed)|compar(?:ed)', word):
        return -0.8
    if re.fullmatch(r'(?:inter)?link(?:s|ed)?|join(?:s|ed|ing)?', word):
        return -0.5
    if re.fullmatch(r'mix(?:es|ed|ing)?|blend(?:s|ed|ing)?|merg(?:e|es|ed|ing)', word):
        return -1.2
    if re.fullmatch(r'(?:inter)?relat(?:e|es|ed|ing)', word):
        return -0.65
    if re.fullmatch(r'''intertwin(?:e|es|ed|ing)?|(?:inter)?weav(?:e|es|ing)|
                       bridg(?:e|es|ed|ing)|mingl(?:e|es|ed|ing)|
                       harmoniz(?:e|es|ed|ing)''', word, re.X):
        return -2.1
    return 0.0


def predict(tail, token):
    if not token or not token[-1].isalpha():
        return -0.002
    if token.strip() in ('连接', '融合', '比較', '比较', '平衡', '同时', '同時'):
        return -1.1
    if token.strip() in ('兼具', '区分', '區分'):
        return -3.0
    text = tail + token
    match = re.search(r'([^\W\d_]+)\Z', text)
    if not match:
        return -0.002
    raw = match.group()
    word = raw.lower()
    before = text[:match.start()]
    words = re.findall(r'[^\W\d_]+', before.lower())
    # Punctuation breaks the immediate grammatical connection.
    adjacent = words and before.rstrip().lower().endswith(words[-1])
    prev = words[-1] if adjacent else ''
    plural = prev.endswith('s') and prev not in ('synthesis', 'series')
    noun = prev[:-1] if plural else prev

    if word in ('tra', 'fra'):
        return -8.5 if sum(w in ITALIAN for w in words[-18:]) >= 2 else -1.15
    if word in BETWEEN:
        if word == 'between' and noun in ('difference', 'distinction', 'choice'):
            return -3.8
        if (word == 'between' and noun in
                ('border', 'edge', 'gap', 'path', 'bridge', 'intermediate')):
            return -6.5
        return BETWEEN[word]
    if word.endswith('between'):
        return -3.1
    if word == 'both':
        return -1.35 if raw[0].isupper() else -2.0
    if word in ('både', 'båda'):
        return -3.3
    if word in ('among', 'amongst'):
        related = noun in RELATIONS | MEASURES | {'difference', 'distinction'}
        return -4.5 if related else -1.3
    if word in ('simultaneous', 'simultaneously', 'concurrently'):
        return -3.3
    if word in ('together', 'jointly'):
        if prev in ('bring', 'brings', 'bringing', 'brought'):
            return -4.0
        return -0.77 if word == 'together' else -1.6
    if word == 'ratio' and prev == 'common':
        return 3.9

    if word == 'of':
        if prev == 'product':
            return -6.2
        if (prev in ('gcd', 'lcm')
                or (prev == 'divisor' and 'common' in words[-4:-1])):
            return -5.8
        if prev == 'ratio':
            return -4.3
        if prev == 'products':
            return -2.5
        if prev in ('divisor', 'divisors'):
            return -0.02
        if noun in MIXTURES:
            organization = before.rstrip().endswith('Union')
            return -2.2 if plural or organization else -6.2
        if noun in OPERATIONS:
            return -2.5 if plural else -4.4
        if noun in ('pair', 'pairing'):
            return -2.0
        modifiers = {'relative', 'combined', 'comparative', 'joint', 'synergistic'}
        if any(w in modifiers for w in words[-3:-1]):
            return -2.8
        if noun in ('sum', 'difference'):
            return -4.0
        if noun in RELATIONS:
            return -3.8
        if noun in MEASURES:
            return -1.1
        if noun in ('mean', 'average'):
            return -2.0
        if noun == 'total':
            return -0.7
        if noun in COLLECTIONS:
            return -0.45
        if prev in ('maximum', 'minimum', 'max', 'min', 'lesser',
                    'greater', 'smallest', 'largest'):
            return -1.3
        modified = (prev in ('up', 'only', 'solely')
                    and any(w in COMPOSITION | {'made'} for w in words[-3:-1]))
        if prev in COMPOSITION or modified:
            return -1.8
        return -0.02
    if (word in ('de', 'di') and prev in
            ('combinación', 'combinacion', 'mezcla', 'combinaison',
             'mélange', 'combinazione', 'miscela')):
        return -4.0
    if word == 'from':
        if prev in PATHS:
            return -1.7
        if prev in ('different', 'distinct', 'separate', 'separated',
                    'apart', 'away', 'differ', 'differs'):
            return 0.0
        return -0.25
    if word == 'by' and prev in ('formed', 'shared'):
        return -2.8 if prev == 'formed' else -4.0
    if word in ('the', 'a', 'an', 'two', 'these', 'those'):
        if prev in BETWEEN:
            return -1.45 if word == 'the' else -0.44
        if verb_value(prev):
            strong_article = word == 'the' and verb_value(prev) <= -1.5
            return -1.95 if strong_article else -0.45
    if (word in ('connecting', 'connects', 'joining', 'relating', 'relates')
            and prev in ('line', 'path', 'curve', 'equation')):
        return -7.5
    if word in ('comprise', 'comprises', 'comprising'):
        return -0.7
    if word in ('multiply', 'multiplying'):
        return -1.4
    return verb_value(word) or -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(tail, token)
    return (doc, (tail + token)[-160:]), value

programs.haiku:
"""layers.1.mlp.down_proj:3005 -- a "two-ended relation" detector.

The component goes negative on the word that opens a relation between two things, before
the two things are named. It reads only the newest token (and the one before it):
  * "between" and its translations (entre, fra, tra, zwischen, между): strongest, about -4.
  * "of" right after a combining noun: "product of", "sum of", "ratio of", "blend of",
    "mix of", "union of", "combination of" (the two operands follow): about -4.
  * "among", and words of joining or comparing (both, connect, combine, link, join,
    compare, mix, blend, relate, merge, together): about -1.3 to -1.5.
  * "from" in a path or distance phrase ("path from", "distance from", "goes from",
    "from X to Y"): about -2.5; other "from" is about -0.2; everything else is 0.
The program keeps no state and predicts one fixed value per class.
"""

READS = ()

BETWEEN = {"between", "entre", "fra", "tra", "zwischen", "между", "ween"}
AMONG = {"among"}
PAIRING = {
    "both", "connect", "connects", "connecting", "combine", "combines", "combining",
    "combined", "link", "links", "linking", "joining", "join", "compare", "comparing",
    "compared", "mix", "mixing", "blend", "relate", "relates", "related", "merge",
    "interconnected", "simultaneously", "together", "respectively", "jointly",
}
COMBINING_NOUNS = {
    "product", "products", "sum", "ratio", "ratios", "blend", "mix", "mixture", "union",
    "intersection", "combination", "comparison", "difference", "interaction", "convolution",
    "fusion", "equivalence", "divisor", "quotient", "coupling", "separation", "relationship",
    "correlation", "association", "pairing", "synthesis", "integration", "average", "mean",
}
GROUP_NOUNS = {
    "consists", "consist", "consisting", "composed", "comprised", "comprising", "pair", "pairs",
    "mean", "average", "maximum", "minimum", "system", "collection", "association",
}
MOTION_NOUNS = {
    "path", "paths", "distance", "range", "goes", "going", "go", "segment", "edge", "map",
    "transformation", "transition", "shift", "travels", "moving", "ranging", "line", "vector",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in BETWEEN:
        value = -4.2
    elif word == "of" and before in COMBINING_NOUNS:
        value = -4.3
    elif word == "of" and before in GROUP_NOUNS:
        value = -2.0
    elif word in AMONG:
        value = -1.5
    elif word in PAIRING:
        value = -1.3
    elif word == "from":
        value = -2.5 if before in MOTION_NOUNS else -0.2
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A sparse double-underscore and code-lexeme signal, not a language parser.

Positive values mark closing Python special names and doubled-underscore path
separators, strongest before a slash. Opening underscores are weak or negative,
except for a high baseline on a document-initial bare double underscore.
Smaller branches cover underscore/leader punctuation and selected code words.
The word responses are lexical averages, not a semantic distinction from prose.
Only the current path/word segment is carried, reset at document boundaries.
"""
import re

READS = ()

# These are language constructs, not arbitrary vocabulary IDs.
CODE_WORDS = {
    'require': -1.7,
    'assert': -1.8,
    'import': -0.65,
    'impl': -1.8,
    'exports': -2.4,
    'module': -1.0,
    'global': -1.1,
    'define': -0.8,
    'crate': -1.4,
}


def activation(token, tail):
    if token.startswith('__') and not token.startswith('___'):
        suffix = token[2:]
        if not suffix or not any(c.isalnum() for c in suffix):
            dunder = re.search(r'(?<!\w)__[A-Za-z]\w*$', tail)
            if suffix.startswith('/'):
                return 10.0 if dunder else 6.2
            if suffix == '.__':
                return 1.8
            if suffix.startswith('.'):
                return 4.8
            if suffix.startswith('('):
                return 2.6
            if suffix:
                return 2.0 if '__' in tail else 0.4
            if dunder:
                return 5.0
            if '__' in tail:
                return 2.3
            return 0.45 if tail[-1:].isalnum() else -0.2
    if token in (' __', '\t__', '.__', '(__', '::__'):
        return -0.85
    if token == ' _':
        return 0.42
    if re.fullmatch(r'_+\n+', token):
        return 1.4
    if token == '_\\':
        return 0.65
    if token == '··':
        return 0.93
    if token == '::':
        return -0.4
    word = token.lstrip(' \t.(')
    if word in CODE_WORDS:
        return CODE_WORDS[word]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    value = 4.7 if first and token == '__' else activation(token, tail)
    # Keep just the current path/word-like segment for underscore matching.
    tail = re.split(r'[\s/\\]', tail + token)[-1][-120:]
    return (doc, tail), float(value)

programs.haiku:
"""Layer 1 MLP down-projection, component 3006.

What it does: this component is mostly silent, but it has big, readable events.

1. Dunder names. The closing "__" of a Python/JS dunder name (__init__, __name__,
   __main__, __slots__, ..., and the "__" that ends a __tests__ folder) pushes the
   activation strongly positive. A "__" that opens a dunder name (" __" with a space)
   pushes it slightly negative. Other "__" tokens, such as the "__" between the owner and
   repo in package paths like "owner__repo__1.0", are mildly positive.
2. Module-system and code keywords. In JavaScript, "require" after "=" or "const/var/let"
   (as in `const x = require('y')`) is strongly negative; in prose "require" is near zero.
   "assert" (Rust and Python test macros), "impl", Rust "use" and "_use" (#[macro_use]),
   "::" paths, "import", and "module"/"exports" are negative by smaller amounts.

3. Underscore blanks. Escaped underscores used as a fill-in blank ("\\_\\_\\_") are mildly
   positive.

Everything else is predicted as 0. The diffuse small activations in ordinary prose and code
are not modelled. The values are rough means, not fitted to the eval rows.
"""

READS = ()

# Common Python dunder attribute names: a closing "__" after one of these is a strong event.
WELL_KNOWN = {"init", "name", "main", "future", "slots", "class", "args", "origin", "file",
              "version", "doc"}
ASSERT_WORDS = {" assert", "assert", "\tassert"}
IMPORT_WORDS = {" import", "import", "\timport"}
MODULE_WORDS = {"module", " module", "exports"}


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    tok = strings[-1]
    prev = strings[-2] if len(strings) > 1 else ""
    recent = strings[-6:-1]

    if "__" in tok:
        if tok.startswith(" __"):
            return carry, -1.0  # opening dunder, with a leading space
        # A closing "__" after an opening "__" a few tokens back, e.g. __init__ or __name__.
        opened = any("__" in s for s in strings[-6:-1])
        if opened and prev[-1:].isalnum():
            if prev == "tests":
                return carry, 8.0  # __tests__ folders
            return carry, 4.0 if prev in WELL_KNOWN else 2.0
        return carry, 0.5  # other "__" (package names, etc.)

    if tok.startswith("_\\"):
        return carry, 1.5  # escaped underscore blanks, as in "\\_\\_\\_"
    if tok == " require":
        in_js = any(s.strip() in ("=", "const", "var", "let") for s in recent)
        return carry, -6.0 if in_js else -0.3
    if tok in ASSERT_WORDS:
        return carry, -2.0
    if tok in (" impl", "impl"):
        return carry, -1.8
    if tok in ("_use", "\tuse"):
        return carry, -3.0
    if tok == "::":
        return carry, -1.0
    if tok in IMPORT_WORDS:
        return carry, -0.5
    if tok in MODULE_WORDS:
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""Approximate a clause-opening determiner feature, chiefly English 'the'.

The article receives a large positive value after sentence/clause boundaries
and clause introducers; prepositions suppress that value. Capitalization,
word boundaries and token spacing distinguish prose from word fragments.
Possessives and other determiners receive weaker responses. Document-initial
tokens have separate offsets based on case and grammatical class.
WordNet supplies lemmas and broad word classes for the fallback rule.
"""

from functools import lru_cache
import wordnet

READS = ()

PREPOSITIONS = set('''of in to for on at from with by into onto upon over under
above below through across around near along against without within during
per via toward towards beyond among throughout'''.split())
CLAUSE_LINKS = set('''that if unless whether because although though since
whereas lest which where what'''.split())
TIME_LINKS = set('when while whenever wherever until once how'.split())
SENTENCE_ADVERBS = set('''then therefore thus hence however nevertheless
perhaps maybe certainly surely apparently presumably probably possibly
obviously clearly hopefully fortunately unfortunately'''.split())
POSSESSIVES = set('my your our his her their its whose'.split())
COPULAS = set('is are was were be been being am'.split())
QUANTIFIERS = set('''all both each every some any no neither either
such many much few most several'''.split())
CLAUSE_VERBS = set('''think believe assume suppose expect hope know say
mean imply suggest claim realize imagine'''.split())


@lru_cache(maxsize=8192)
def lexical_opening(word, capital):
    bases = {word, *wordnet.base_forms(word)}
    if bases & CLAUSE_VERBS:
        return 0.95
    if capital:
        return 0.45
    parts = wordnet.parts_of_speech(word)
    if 'verb' in parts:
        return 0.17
    if 'adverb' in parts:
        return 0.47
    if 'noun' in parts:
        return 0.32
    return 0.22


def opening(previous, capital):
    """Strength of a noun-phrase opening signalled by the preceding token."""
    w = previous.strip().lower()
    if w.startswith('<|'):
        return -1.5
    if not w:
        return 1.25 if '\n' not in previous else 1.0
    if all(not c.isalnum() for c in w):
        if '.' in w:
            return 1.18 if '\n' in previous else 1.33
        if '\n' in previous:
            return 1.08
        if ',' in w or ';' in w:
            return 0.42 if capital else 1.28
        if ':' in w:
            return 0.95
        if '?' in w or '!' in w:
            return 1.06
        return 0.62 if any(c in w for c in '(\"[“') else 0.85
    if w in PREPOSITIONS:
        return -0.12 if capital else 0.04 + 0.22 * previous.strip().istitle()
    if w in {'as', 'like'}:
        return 0.6
    if w == 'including':
        return 0.74
    if w == 'between':
        return 0.30
    if w in {'about', 'before', 'than'}:
        return 0.47
    if w == 'after':
        return 0.21
    if w in CLAUSE_LINKS or w in SENTENCE_ADVERBS or w in {'but', 'so'}:
        return 1.30
    if w in TIME_LINKS:
        return 1.10
    if w in {'and', 'or', 'nor', 'yet'}:
        return 0.05 if capital else (0.70 if w in {'or', 'nor'} else 0.92)
    if w in COPULAS:
        return 0.34
    if w in QUANTIFIERS:
        return 0.5 if w == 'both' else 0.02
    if w in {"'s", '’s'}:
        return 0.58
    return lexical_opening(w, capital)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    carry = (doc, token)
    if (not fresh and not token[:1].isspace() and previous
            and (previous[-1].isalnum() or previous[-1] == '_')):
        return carry, -0.3 if word == 'the' else 0.0
    if word == 'the':
        capital = token.strip().istitle()
        if fresh:
            value = -1.5 if capital else -0.79
        else:
            value = opening(previous, capital)
            if token == 'the':
                value -= 0.45
            if token.strip().isupper():
                value *= 0.6
        return carry, value
    if word in POSSESSIVES:
        if fresh:
            return carry, -0.9 if token.strip().istitle() else -0.27
        strength = opening(previous, False)
        return carry, 0.42 * strength - 0.10
    if word in {'a', 'an', 'this', 'that', 'these', 'those'}:
        if fresh:
            capital = token.strip().istitle()
            if word in {'a', 'an'}:
                return carry, 0.10 if capital else -0.43
            return carry, 0.31 if capital else -0.19
        p = previous.strip().lower()
        if p in PREPOSITIONS or p in COPULAS:
            return carry, -0.04
        return carry, 0.13 * max(0.0, opening(previous, False)) - 0.025
    if fresh:
        if token.startswith('<'):
            return carry, 0.3
        return carry, -0.33 if token.strip().istitle() else -0.17
    return carry, 0.0

