"""Program v3: the determiner 'the' (and a few other determiners) opening a new clause.

Activation fires on determiners, mostly 'the', that start a clause or sentence (the
subject of a new clause). It is near zero when the determiner follows a preposition or
a verb (object position)."""

READS = ()

BOUNDARY = set(".,:;!?\n\"'()[]")                  # punctuation that closes a clause
CLAUSE_STARTERS = {"that", "if", "when", "where", "which", "but", "then", "so", "unless",
                   "perhaps", "while", "because", "once", "until", "whether", "though",
                   "since", "maybe", "thus", "wait", "think"}
JOINERS = {"and", "or", "as", "including", "than", "about", "before", "after", "between"}
COPULAS = {"is", "are", "was", "were", "be", "been", "use", "using", "have", "get", "by"}
PREPOSITIONS = {"of", "in", "at", "to", "from", "into", "over", "through", "along", "for",
                "on", "with", "during", "within", "under"}
POSSESSIVES = {"my", "your", "his", "her", "their", "its", "our"}
WEAK_DETERMINERS = {"a", "an", "this", "each"}
# how strongly each determiner fires at the start of a clause
STRENGTH = {"the": 1.3, **{w: 0.4 for w in POSSESSIVES}, **{w: 0.15 for w in WEAK_DETERMINERS}}


def step(carry, prefix, upstream):
    """Activation of the determiner at this position (0 for every other word)."""
    word = prefix.token_strings[-1].strip().lower()
    if word not in STRENGTH:
        return carry, 0.0
    strength = STRENGTH[word]
    if len(prefix.token_strings) < 2:
        return carry, strength
    prev = prefix.token_strings[-2].strip().lower()
    if prev == "<|endoftext|>":
        return carry, -1.5 if word == "the" else 0.0
    if prev == "" or prev[-1:] in BOUNDARY or prev in CLAUSE_STARTERS:
        return carry, strength                     # opens a new clause: fires fully
    if prev in JOINERS:
        return carry, 0.6 * strength
    if prev in PREPOSITIONS:
        return carry, 0.0                          # object of a preposition: silent
    if prev in COPULAS:
        return carry, 0.25 * strength
    return carry, 0.2 * strength                   # object of a verb or other word
